INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('" yet. We are adding the best-known kids'' foods first, and what you search for helps us choose. Try one word, like "oats" or "ragi".', 'id', '" belum. Kami menambahkan makanan anak yang paling dikenal lebih dulu, dan apa yang Anda cari membantu kami memilih. Coba satu kata, misalnya "oat" atau "ragi".', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('">Open it', 'id', '">Buka', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('"No Added<br_a/>Preservatives"', 'id', '"Tanpa<br_a/>Pengawet"', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('"The label wasn''t lying. It just wasn''t written for someone standing in an aisle with fifteen seconds and a tired kid."', 'id', 'Labelnya tidak berbohong. Hanya saja labelnya tidak ditulis untuk orang yang berdiri di lorong toko dengan waktu lima belas detik dan anak yang lelah.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES (', built with parents.', 'id', ', dibuat bersama orang tua.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES (', so you can open them on another phone or computer.', 'id', ', agar Anda bisa membukanya di ponsel atau komputer lain.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('. Pick your child''s age on Meal Ideas or Products to change it.', 'id', '. Pilih usia anak Anda di Ide Menu atau Produk untuk mengubahnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('. Scores are for that age. Best score first, among the ones that fit.', 'id', '. Skor berlaku untuk usia itu. Skor terbaik lebih dulu, di antara yang cocok.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('. Thank you for helping us get it right.', 'id', '. Terima kasih sudah membantu kami agar tepat.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('. The score comes from the nutrition table and the ingredients on your back photo.', 'id', '. Skor dihitung dari tabel gizi dan daftar bahan pada foto bagian belakang kemasan Anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('. Try leaving out the taste or the meal, or a different age.', 'id', '. Coba tanpa rasa atau waktu makan tertentu, atau pilih usia lain.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<a_a>Home</a_a> › Compare', 'id', '<a_a>Beranda</a_a> › Bandingkan', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<a_a>Home</a_a> › Recipes', 'id', '<a_a>Beranda</a_a> › Resep', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<a_a>See every recipe</a_a>, each with its own page and score, or <a_b>browse ideas by taste, meal and age</a_b>.', 'id', '<a_a>Lihat semua resep</a_a>, masing-masing dengan halaman dan skornya sendiri, atau <a_b>jelajahi ide menurut rasa, waktu makan, dan usia</a_b>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>A random id kept in your browser</b_a> (no name, number or IP address is stored with it). It lets us count how many different browsers visit and show you recipes you have not seen yet when you repeat a search. Your browser also keeps your chosen filters, shopping ticks and login token on your device. We do not use advertising or tracking cookies.', 'id', '<b_a>Kode acak yang disimpan di peramban Anda</b_a> (tanpa nama, nomor, atau alamat IP yang disimpan bersamanya). Kode ini membantu kami menghitung berapa banyak peramban berbeda yang berkunjung dan menampilkan resep yang belum Anda lihat saat Anda mengulang pencarian. Peramban Anda juga menyimpan filter pilihan, centang belanja, dan token masuk di perangkat Anda. Kami tidak menggunakan cookie iklan atau pelacakan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Hundreds of</b_a> recipes, by age, meal, season and food preference. Save the ones you like, then put them into a plan for the week: breakfast, lunch, a {#} PM snack and dinner, for every day.', 'id', '<b_a>Ratusan</b_a> resep, menurut usia, waktu makan, musim, dan pilihan makanan. Simpan yang Anda suka, lalu susun menjadi rencana seminggu: sarapan, makan siang, camilan pukul {#} sore, dan makan malam, untuk setiap hari.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Is this your pack?</b_a> On a pack that is not yet checked, tell us if the name on your pack is different. Then photograph yours, and it is scored from your photos.', 'id', '<b_a>Apakah ini kemasan Anda?</b_a> Pada kemasan yang belum diperiksa, beri tahu kami jika nama di kemasan Anda berbeda. Lalu foto kemasan Anda, dan skornya dihitung dari foto Anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Mistake reports and your optional email.</b_a> If you report a mistake on a pack, we keep what you wrote and the pack it is about. If you leave an email (with a report or with photos), we use it once, to thank you when the pack is checked or to tell you what we did, and for nothing else. Leaving it is always optional. When you send photos you tick a box to say they are of a pack you have and that KidPoshan may show them and use them to score the pack.', 'id', '<b_a>Laporan kesalahan dan email opsional Anda.</b_a> Jika Anda melaporkan kesalahan pada sebuah kemasan, kami menyimpan apa yang Anda tulis dan kemasan yang dimaksud. Jika Anda mengisi email (bersama laporan atau foto), kami menggunakannya sekali, untuk berterima kasih saat kemasan sudah diperiksa atau memberi tahu apa yang kami lakukan, dan tidak untuk hal lain. Mengisinya selalu opsional. Saat mengirim foto, Anda mencentang kotak yang menyatakan bahwa foto itu dari kemasan yang Anda miliki dan bahwa KidPoshan boleh menampilkannya serta menggunakannya untuk menilai kemasan tersebut.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Name, mobile number and email address</b_a>, only if you give them (when you rate a recipe, send a remark, or fill in the small "Join KidPoshan" box on a recipe page). We use them to know who rated a recipe or wrote a remark. We do not check that a number or address is yours. Your mobile number and email are <b_b>never shown</b_b> on the site. Your name is shown only next to a remark that our team has approved.', 'id', '<b_a>Nama, nomor ponsel, dan alamat email</b_a>, hanya jika Anda memberikannya (saat Anda menilai resep, mengirim komentar, atau mengisi kotak kecil "Gabung KidPoshan" di halaman resep). Kami menggunakannya untuk mengetahui siapa yang menilai resep atau menulis komentar. Kami tidak memeriksa apakah nomor atau alamat itu milik Anda. Nomor ponsel dan email Anda <b_b>tidak pernah ditampilkan</b_b> di situs. Nama Anda hanya ditampilkan di samping komentar yang sudah disetujui tim kami.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Open Food Facts</b_a>, a free database of food products made by people around the world (<a_b>openfoodfacts.org</a_b>, Open Database Licence). We credit it on every page that uses it.', 'id', '<b_a>Open Food Facts</b_a>, basis data produk makanan gratis yang dibuat oleh orang-orang di seluruh dunia (<a_b>openfoodfacts.org</a_b>, Open Database Licence). Kami mencantumkannya di setiap halaman yang menggunakannya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Optional ₹{#} support.</b_a> You pay in your own UPI app; we never see your bank or card details. If you tell us you have paid, we keep the amount, the time and the payment reference you typed, so we can confirm it.', 'id', '<b_a>Dukungan opsional ₹{#}.</b_a> Anda membayar lewat aplikasi UPI Anda sendiri; kami tidak pernah melihat data bank atau kartu Anda. Jika Anda memberi tahu kami bahwa Anda sudah membayar, kami menyimpan jumlah, waktu, dan referensi pembayaran yang Anda ketik, agar kami dapat mengonfirmasinya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Packs you scan.</b_a> When you scan a barcode we look the pack up. If you send photos of a pack, we keep the barcode and the two photos, and read the nutrition label from the back photo. The photos may be shown with the pack on the Products page after our team has checked it, so please photograph only the pack and not people. We keep no name, number or address with a scan. To stop one phone sending too many, we keep a one-day code made from your connection (not your IP address) for two days.', 'id', '<b_a>Kemasan yang Anda pindai.</b_a> Saat Anda memindai kode batang, kami mencari kemasan itu. Jika Anda mengirim foto kemasan, kami menyimpan kode batang dan dua foto, lalu membaca label gizi dari foto belakang. Foto dapat ditampilkan bersama kemasan di halaman Produk setelah tim kami memeriksanya, jadi mohon foto kemasannya saja, bukan orang. Kami tidak menyimpan nama, nomor, atau alamat bersama pemindaian. Agar satu ponsel tidak mengirim terlalu banyak, kami menyimpan kode satu hari yang dibuat dari koneksi Anda (bukan alamat IP Anda) selama dua hari.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Photos from parents:</b_a> the front and back of a pack. Our label reader reads the table, and our team checks the numbers against the photo before a pack is marked checked.', 'id', '<b_a>Foto dari orang tua:</b_a> bagian depan dan belakang kemasan. Pembaca label kami membaca tabelnya, dan tim kami memeriksa angkanya dengan foto sebelum kemasan ditandai sudah diperiksa.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Ratings and remarks</b_a> you submit. A remark appears on the site only after our team approves it, and you can ask us to remove it.', 'id', '<b_a>Penilaian dan komentar</b_a> yang Anda kirim. Komentar baru muncul di situs setelah disetujui tim kami, dan Anda dapat meminta kami menghapusnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Report a mistake</b_a> on any pack: a wrong name, numbers that do not match the label, or a wrong photo.', 'id', '<b_a>Laporkan kesalahan</b_a> pada kemasan mana pun: nama yang salah, angka yang tidak sesuai dengan label, atau foto yang salah.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Saved recipes and your weekly plan</b_a> stay on your phone. Only if you choose to use them on another device do we ask for your mobile number and a one-time code sent by SMS; the saved list is then stored under that verified number so nobody else can open it.', 'id', '<b_a>Resep tersimpan dan rencana mingguan Anda</b_a> tetap ada di ponsel Anda. Hanya jika Anda memilih memakainya di perangkat lain, kami meminta nomor ponsel Anda dan kode sekali pakai lewat SMS; daftar tersimpan lalu disimpan di bawah nomor yang terverifikasi itu agar tidak ada orang lain yang dapat membukanya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Scan a pack</b_a> we do not have, and photograph its front and back.', 'id', '<b_a>Pindai kemasan</b_a> yang belum kami miliki, dan foto bagian depan dan belakangnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>The pack''s own label:</b_a> the nutrition table and the ingredient list, per {#} g, as printed.', 'id', '<b_a>Label kemasan itu sendiri:</b_a> tabel gizi dan daftar bahan, per {#} g, sebagaimana tercetak.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>What is a citation and what is our own judgment:</b_a> the daily references behind checks {#}, {#}, {#}, {#} and {#} come from [{#}] to [{#}], except the child sodium limit, which is our scaling of [{#}] (see [{#}]). Checks {#}, {#} and {#} test the ingredient list against FSSAI rules [{#}] and [{#}]. Check {#} echoes the high-in-fat-sugar-or-salt idea in [{#}], but the rule itself is ours. These parts are our own choices, applied the same way every time: the line a serving must stay under ({#}% of the day, {#}% for snacks, sweets and sweet drinks) to pass sugar, sodium and saturated fat; the {#}% of the day a serving must give to pass fibre and protein; the base-ingredient check ({#}); which foods count as snacks; and holding a pack at OK when a risk check fails. The {#}% line is also the one the UK''s traffic-light labels use for a portion. Under {#} months there is no published reference band, so the {#} to {#} year reference is used. Pregnant and lactating women and the elderly are not scored yet.', 'id', '<b_a>Mana yang kutipan dan mana penilaian kami sendiri:</b_a> acuan harian di balik pemeriksaan {#}, {#}, {#}, {#}, dan {#} berasal dari [{#}] sampai [{#}], kecuali batas natrium anak, yang merupakan penskalaan kami atas [{#}] (lihat [{#}]). Pemeriksaan {#}, {#}, dan {#} menguji daftar bahan terhadap aturan FSSAI [{#}] dan [{#}]. Pemeriksaan {#} mengikuti gagasan tinggi-lemak-gula-atau-garam di [{#}], tetapi aturannya sendiri adalah milik kami. Bagian-bagian ini adalah pilihan kami sendiri, diterapkan dengan cara yang sama setiap kali: batas yang harus tidak dilampaui satu sajian ({#}% dari kebutuhan sehari, {#}% untuk camilan, makanan manis, dan minuman manis) agar lulus gula, natrium, dan lemak jenuh; {#}% dari kebutuhan sehari yang harus dipenuhi satu sajian agar lulus serat dan protein; pemeriksaan bahan dasar ({#}); makanan mana yang dihitung sebagai camilan; dan menahan kemasan di Cukup bila satu pemeriksaan risiko gagal. Batas {#}% juga dipakai label lampu lalu lintas di Inggris untuk satu porsi. Di bawah {#} bulan tidak ada rentang acuan yang dipublikasikan, jadi acuan usia {#} sampai {#} tahun digunakan. Ibu hamil dan menyusui serta lansia belum dinilai.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Which pages are opened and for how long.</b_a> For each page view we keep the page, the time, how long it stayed on screen, and the country and city your connection appears to be in. We do not keep your IP address. This is only for our own anonymous visit statistics; crawlers and monitors are not counted as visitors, and these records are deleted after about {#} months.', 'id', '<b_a>Halaman mana yang dibuka dan berapa lama.</b_a> Untuk setiap kunjungan halaman kami menyimpan halamannya, waktunya, berapa lama halaman itu tampil di layar, serta negara dan kota tempat koneksi Anda tampaknya berada. Kami tidak menyimpan alamat IP Anda. Ini hanya untuk statistik kunjungan anonim kami sendiri; perayap dan monitor tidak dihitung sebagai pengunjung, dan catatan ini dihapus setelah sekitar {#} bulan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Your email address and your choices, for the weekly tiffin email</b_a>, only if you sign up at <a_b>kidposhan.in/newsletter</a_b>: the address, your child''s age group and food preference, and when you agreed. We send a first email to confirm it is yours, and nothing more until you confirm. Every email has a one-click unsubscribe link, and after you unsubscribe we send nothing. Your address is used only for this email and is not shared. To have it deleted, write to <a_c>kidposhan@gmail.com</a_c>.', 'id', '<b_a>Alamat email dan pilihan Anda, untuk email bekal mingguan</b_a>, hanya jika Anda mendaftar di <a_b>kidposhan.in/newsletter</a_b>: alamatnya, kelompok usia anak Anda dan pilihan makanannya, serta kapan Anda menyetujui. Kami mengirim email pertama untuk memastikan alamat itu milik Anda, dan tidak ada lagi sampai Anda mengonfirmasi. Setiap email memiliki tautan berhenti berlangganan satu klik, dan setelah Anda berhenti kami tidak mengirim apa pun. Alamat Anda hanya dipakai untuk email ini dan tidak dibagikan. Untuk menghapusnya, tulis ke <a_c>kidposhan@gmail.com</a_c>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI compliance affidavit, Supreme Court of India, W.P.(C) No. {#}/{#} — {#}S and Our Health Society vs Union of India, filed {#} August {#}.</b_a> Proposes a front-of-pack red hexagon warning for foods high in added saturated fat, added sugar, and/or salt (HFSS), with thresholds to be drawn from the <i_b>Dietary Guidelines for Indians, {#}</i_b> (ICMR-NIN). This is a live, pending proceeding — not yet a notified regulation.', 'id', '<b_a>[{#}] Affidavit kepatuhan FSSAI, Mahkamah Agung India, W.P.(C) No. {#}/{#} — {#}S and Our Health Society vs Union of India, diajukan {#} Agustus {#}.</b_a> Mengusulkan peringatan segi enam merah di bagian depan kemasan untuk makanan tinggi lemak jenuh tambahan, gula tambahan, dan/atau garam (HFSS), dengan ambang batas yang diambil dari <i_b>Dietary Guidelines for Indians, {#}</i_b> (ICMR-NIN). Ini adalah proses yang masih berjalan, bukan peraturan yang sudah diberlakukan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI, Food Safety and Standards (Food Products Standards and Food Additives) Regulations, {#}.</b_a> Governs permitted preservatives (Class II) and additives (colours, flavour enhancers) by INS number.', 'id', '<b_a>[{#}] FSSAI, Food Safety and Standards (Food Products Standards and Food Additives) Regulations, {#}.</b_a> Mengatur pengawet yang diizinkan (Kelas II) dan bahan tambahan (pewarna, penguat rasa) menurut nomor INS.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI, Food Safety and Standards (Prohibition and Restrictions on Sales) Regulations.</b_a> Trans fat capped at ≤{#}% of total oils and fats in any food product, all ages, all categories.', 'id', '<b_a>[{#}] FSSAI, Food Safety and Standards (Prohibition and Restrictions on Sales) Regulations.</b_a> Lemak trans dibatasi paling banyak {#}% dari total minyak dan lemak pada produk makanan apa pun, untuk semua usia dan semua kategori.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] ICMR-NIN (National Institute of Nutrition), "Nutrient Requirements for Indians: Recommended Dietary Allowances and Estimated Average Requirements," {#}.</b_a> The source for the energy requirement, protein RDA and dietary fibre RDA of every group on this page: children {#}–{#}, {#}–{#} and {#}–{#}; boys and girls {#}–{#}, {#}–{#} and {#}–{#}; men and women at sedentary, moderate and heavy work. It also gives the adult sodium limit of {#} mg a day ({#} g of salt), which it takes from WHO ({#}).', 'id', '<b_a>[{#}] ICMR-NIN (National Institute of Nutrition), "Nutrient Requirements for Indians: Recommended Dietary Allowances and Estimated Average Requirements," {#}.</b_a> Sumber kebutuhan energi, AKG protein, dan AKG serat pangan untuk setiap kelompok di halaman ini: anak {#}–{#}, {#}–{#}, dan {#}–{#}; anak laki-laki dan perempuan {#}–{#}, {#}–{#}, dan {#}–{#}; pria dan wanita dengan kerja ringan, sedang, dan berat. Sumber ini juga memberi batas natrium dewasa {#} mg per hari ({#} g garam), yang diambilnya dari WHO ({#}).', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] Serving sizes.</b_a> The serving printed on the pack. Where a pack prints none, a reference amount for that kind of food, taken from the US FDA''s "reference amounts customarily consumed" ({#} CFR {#}) where one fits, and our own estimate where none does.', 'id', '<b_a>[{#}] Ukuran sajian.</b_a> Sajian yang tercetak di kemasan. Bila kemasan tidak mencetaknya, digunakan takaran acuan untuk jenis makanan itu, diambil dari "reference amounts customarily consumed" milik US FDA ({#} CFR {#}) bila ada yang cocok, dan perkiraan kami sendiri bila tidak ada.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO guidance on saturated fat</b_a> (the {#} guideline on saturated and trans fatty acid intake, and the FAO/WHO fats consultations). Saturated fat under {#}% of energy, converted to grams at {#} kcal/g.', 'id', '<b_a>[{#}] Panduan WHO tentang lemak jenuh</b_a> (pedoman {#} tentang asupan asam lemak jenuh dan trans, serta konsultasi FAO/WHO tentang lemak). Lemak jenuh di bawah {#}% energi, diubah menjadi gram dengan {#} kkal/g.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO, "Guideline: Sodium intake for adults and children," {#}.</b_a> For children the adult limit is lowered in line with their lower energy needs. ICMR-NIN {#} gives no child figure, so we apply that rule ourselves: the {#} mg adult limit scaled by each group''s energy, about {#} mg per kcal, never above {#} mg. These child limits are our calculation, not a published figure.', 'id', '<b_a>[{#}] WHO, "Guideline: Sodium intake for adults and children," {#}.</b_a> Untuk anak, batas dewasa diturunkan sesuai kebutuhan energi mereka yang lebih rendah. ICMR-NIN {#} tidak memberi angka untuk anak, jadi kami menerapkan aturan itu sendiri: batas dewasa {#} mg diskalakan menurut energi tiap kelompok, sekitar {#} mg per kkal, tidak pernah di atas {#} mg. Batas anak ini adalah perhitungan kami, bukan angka yang dipublikasikan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO, "Guideline: Sugars intake for adults and children," {#}.</b_a> Free sugars under {#}% of energy, with further benefit below {#}%. We use {#}% of each group''s energy as the daily ideal and {#}% as the upper limit, converted to grams at {#} kcal/g.', 'id', '<b_a>[{#}] WHO, "Guideline: Sugars intake for adults and children," {#}.</b_a> Gula bebas di bawah {#}% energi, dengan manfaat tambahan di bawah {#}%. Kami memakai {#}% dari energi tiap kelompok sebagai batas ideal harian dan {#}% sebagai batas atas, diubah menjadi gram dengan {#} kkal/g.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>{#} m–adult</b_a><span_b>every score worked out for the age group</span_b>', 'id', '<b_a>{#} bln–dewasa</b_a><span_b>setiap skor dihitung untuk kelompok usianya</span_b>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
