INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification · No brand pays to be here', 'id', 'Dibandingkan dengan <b_a>ICMR-NIN {#}</b_a> dan <b_b>FSSAI</b_b> · Poshan Score adalah penilaian independen, bukan sertifikasi · Tidak ada merek yang membayar untuk ada di sini', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Dish photos belong to their creators and link back to the original recipe. Pack photos are the sellers''.', 'id', 'Dibandingkan dengan <b_a>ICMR-NIN {#}</b_a> dan <b_b>FSSAI</b_b> · Poshan Score adalah penilaian independen, bukan sertifikasi<br_c/> Foto hidangan milik pembuatnya dan tertaut ke resep aslinya. Foto kemasan milik penjual.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Label data may come from <a_d>Open Food Facts</a_d> contributors (Open Database Licence) or from photos sent by parents and read by our label reader, and is checked before a pack is listed. The age guide is general and cautious. It is not medical advice.', 'id', 'Dibandingkan dengan <b_a>ICMR-NIN {#}</b_a> dan <b_b>FSSAI</b_b> · Poshan Score adalah penilaian independen, bukan sertifikasi<br_c/> Data label dapat berasal dari kontributor <a_d>Open Food Facts</a_d> (Open Database Licence) atau dari foto yang dikirim orang tua dan dibaca pembaca label kami, dan diperiksa sebelum kemasan dicantumkan. Panduan usia bersifat umum dan berhati-hati. Ini bukan nasihat medis.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Pack photos are the sellers'' or, where marked, from <a_d>Open Food Facts</a_d> contributors (CC BY-SA). Some label data comes from Open Food Facts under the Open Database Licence. The age guide is general and cautious. It is not medical advice.', 'id', 'Dibandingkan dengan <b_a>ICMR-NIN {#}</b_a> dan <b_b>FSSAI</b_b> · Poshan Score adalah penilaian independen, bukan sertifikasi<br_c/> Foto kemasan milik penjual atau, bila ditandai, dari kontributor <a_d>Open Food Facts</a_d> (CC BY-SA). Sebagian data label berasal dari Open Food Facts di bawah Open Database Licence. Panduan usia bersifat umum dan berhati-hati. Ini bukan nasihat medis.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a>, <b_b>WHO</b_b> guidance and <b_c>FSSAI</b_c> regulation · Poshan Score is an independent rating, not a certification', 'id', 'Dibandingkan dengan <b_a>ICMR-NIN {#}</b_a>, panduan <b_b>WHO</b_b>, dan peraturan <b_c>FSSAI</b_c> · Poshan Score adalah penilaian independen, bukan sertifikasi', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
