INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Each check below shows exactly what earns a yes and what earns a no. Count the yeses and multiply by {#} to get the score from {#} to {#}. This is why we do not trust the front of the pack: watch what is printed there against what is actually on the back.', 'id', 'Setiap pemeriksaan di bawah menunjukkan dengan tepat apa yang mendapat ya dan apa yang mendapat tidak. Hitung jumlah ya lalu kalikan {#} untuk mendapat skor dari {#} sampai {#}. Inilah sebabnya kami tidak mempercayai bagian depan kemasan: lihat apa yang tercetak di sana dibandingkan dengan apa yang sebenarnya ada di bagian belakang.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Energy kcal', 'id', 'Energi kkal', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Energy, protein and fibre are the ICMR-NIN {#} figures for each group (energy is NIN''s estimated requirement). Added sugar is {#}% of energy (upper {#}%) and saturated fat {#}% of energy (WHO). Sodium is the ICMR-NIN {#} adult limit of {#} mg, scaled down by energy for younger children. The row without a sex is the average of the two.', 'id', 'Energi, protein, dan serat adalah angka ICMR-NIN {#} untuk setiap kelompok (energi adalah perkiraan kebutuhan menurut NIN). Gula tambahan adalah {#}% energi (batas atas {#}%) dan lemak jenuh {#}% energi (WHO). Natrium adalah batas dewasa ICMR-NIN {#} sebesar {#} mg, diturunkan menurut energi untuk anak yang lebih kecil. Baris tanpa jenis kelamin adalah rata-rata keduanya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Estimated from the ingredient list: each ingredient is weighed, and the sugar, salt, saturated fat, fibre and protein of one serving are added up.', 'id', 'Diperkirakan dari daftar bahan: setiap bahan ditimbang, lalu gula, garam, lemak jenuh, serat, dan protein dari satu sajian dijumlahkan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every number on this page, sourced', 'id', 'Setiap angka di halaman ini, lengkap dengan sumbernya', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every pack says <em_a>healthy.</em_a><br_b/>Every recipe says <em_c>wholesome.</em_c><br_d/><span_e>We read what is really inside.</span_e>', 'id', 'Setiap kemasan mengaku <em_a>sehat.</em_a><br_b/>Setiap resep mengaku <em_c>bergizi.</em_c><br_d/><span_e>Kami membaca apa yang sebenarnya ada di dalamnya.</span_e>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every pack says it is healthy. We read the back. Poshan Score is a beta, and it gets better each time a parent adds a pack or corrects one.', 'id', 'Setiap kemasan mengaku sehat. Kami membaca bagian belakangnya. Poshan Score masih beta, dan makin baik setiap kali orang tua menambahkan atau mengoreksi sebuah kemasan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product and every recipe gets <b_a>one score from {#} to {#}</b_a>. Each of the ten checks is a plain <b_b>yes ({#}) or no ({#})</b_b>, and the score is the number passed times {#}, so a product that passes everything scores exactly {#} and one that passes nothing scores {#}. Six of them are numbers off the label, measured as a share of the daily reference for the age group (and, from {#} years, the sex and kind of work): <b_c>added sugar, sodium, saturated fat, trans fat, fibre and protein</b_c>. Fibre and protein are <b_d>credit</b_d> metrics (more is better); the others are <b_e>risk</b_e> metrics (less is better). Three more are checks that do not change with age: <b_f>preservatives, artificial additives and base-ingredient integrity</b_f>. The tenth is <b_g>HFSS</b_g>, which fails if the sugar, sodium or saturated-fat check fails. A product that fails any one risk check is held at <b_h>OK</b_h>: the score still shows the real count, with a "capped" badge. Packs and recipes are scored the same way, per realistic serving, so they can be compared. The same method is used on the Products and Meal Ideas pages. Every number below is cited, and the sources are listed at the bottom of this page.', 'id', 'Setiap produk dan setiap resep mendapat <b_a>satu skor dari {#} sampai {#}</b_a>. Setiap dari sepuluh pemeriksaan adalah <b_b>ya ({#}) atau tidak ({#})</b_b> yang jelas, dan skornya adalah jumlah yang lulus dikali {#}, sehingga produk yang lulus semuanya mendapat tepat {#} dan yang tidak lulus satu pun mendapat {#}. Enam di antaranya adalah angka dari label, diukur sebagai bagian dari acuan harian untuk kelompok usia (dan, mulai usia {#} tahun, jenis kelamin dan jenis pekerjaan): <b_c>gula tambahan, natrium, lemak jenuh, lemak trans, serat, dan protein</b_c>. Serat dan protein adalah metrik <b_d>nilai tambah</b_d> (makin banyak makin baik); yang lain adalah metrik <b_e>risiko</b_e> (makin sedikit makin baik). Tiga lagi adalah pemeriksaan yang tidak berubah menurut usia: <b_f>pengawet, bahan tambahan buatan, dan keaslian bahan dasar</b_f>. Yang kesepuluh adalah <b_g>HFSS</b_g>, yang gagal jika pemeriksaan gula, natrium, atau lemak jenuh gagal. Produk yang gagal pada satu pemeriksaan risiko ditahan di <b_h>Cukup</b_h>: skor tetap menunjukkan jumlah sebenarnya, dengan lencana "dibatasi". Kemasan dan resep dinilai dengan cara yang sama, per sajian yang realistis, sehingga dapat dibandingkan. Metode yang sama dipakai di halaman Produk dan Ide Menu. Setiap angka di bawah dikutip, dan sumbernya tercantum di bagian bawah halaman ini.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product below gets a Poshan Score out of {#}, from the nutrition label printed on the pack, worked out for one realistic serving (the same way recipes are scored, so the two can be compared). The score is made of ten yes-or-no checks, each worth {#} points, and it is worked out for the age you pick. A low score is not a warning. It is a reason to keep it occasional. We search for new products every few hours and read their labels, and a product appears here once its label has been read and checked.', 'id', 'Setiap produk di bawah mendapat Poshan Score dari {#}, dari label gizi yang tercetak di kemasan, dihitung untuk satu sajian yang realistis (dengan cara yang sama seperti resep dinilai, sehingga keduanya bisa dibandingkan). Skor terdiri dari sepuluh pemeriksaan ya-atau-tidak, masing-masing bernilai {#} poin, dan dihitung untuk usia yang Anda pilih. Skor rendah bukan peringatan. Itu alasan untuk memberikannya sesekali saja. Kami mencari produk baru setiap beberapa jam dan membaca labelnya, dan produk muncul di sini setelah labelnya dibaca dan diperiksa.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product we rate is scored on ten yes-or-no checks, for every age group from {#} months to adults: children, boys and girls, men and women.', 'id', 'Setiap produk yang kami nilai dinilai dengan sepuluh pemeriksaan ya-atau-tidak, untuk setiap kelompok usia dari {#} bulan sampai dewasa: anak-anak, anak laki-laki dan perempuan, pria dan wanita.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Everything I kept finding was printed, in compliance with the law, in the correct font size. This wasn''t a story about brands breaking rules — it was a story about how much a food label can get away with saying, technically, truthfully, while still leaving a parent with the wrong picture of what''s actually going into their child. <b_a>The rules were being followed. The point was still being missed.</b_a>', 'id', 'Semua yang terus saya temukan tercetak, sesuai hukum, dengan ukuran huruf yang benar. Ini bukan cerita tentang merek yang melanggar aturan — ini cerita tentang seberapa banyak yang bisa dikatakan sebuah label makanan, secara teknis dan jujur, sambil tetap membuat orang tua memiliki gambaran yang salah tentang apa yang sebenarnya masuk ke tubuh anaknya. <b_a>Aturannya diikuti. Intinya tetap terlewat.</b_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Examples', 'id', 'Contoh', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Feeding kids well felt, for a long time, like it came down to reading the front of a box. "No added sugar." "Rich in fibre." "Trusted by nutritionists." I believed the front the way most parents do — because turning a pack over and reading nine lines of ingredient text in six-point type isn''t something anyone has the time or patience for, standing in an aisle with a child pulling at your sleeve.', 'id', 'Memberi makan anak dengan baik terasa, untuk waktu yang lama, seperti cukup membaca bagian depan kotak. "Tanpa gula tambahan." "Kaya serat." "Dipercaya ahli gizi." Saya percaya bagian depan seperti kebanyakan orang tua — karena membalik kemasan dan membaca sembilan baris teks bahan dengan huruf enam poin bukan hal yang punya waktu atau kesabaran untuk dilakukan siapa pun, berdiri di lorong dengan anak yang menarik-narik lengan baju Anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
