INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Five lunchbox ideas for your child''s age, each scoring Good. Free, one email a week.', 'id', 'Lima ide bekal sesuai usia anak Anda, masing-masing berskor Baik. Gratis, satu email seminggu.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('For a while, the front of the pack was enough.', 'id', 'Untuk sementara, bagian depan kemasan sudah cukup.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('For adults ICMR-NIN {#} gives men and women separately, each at sedentary, moderate and heavy work. Choose men or women, and the kind of work, on the Products and Scan pages; with neither chosen the average of men and women at sedentary work is used. Pregnant and lactating women are not scored yet.', 'id', 'Untuk dewasa ICMR-NIN {#} memberi angka terpisah untuk pria dan wanita, masing-masing pada kerja ringan, sedang, dan berat. Pilih pria atau wanita, dan jenis pekerjaan, di halaman Produk dan Pindai; bila tidak memilih keduanya, digunakan rata-rata pria dan wanita pada kerja ringan. Ibu hamil dan menyusui belum dinilai.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('From various cooks and cookbooks, each credited to the person who wrote it. Scored for the age you pick. <b_a>Tap the heart on any recipe to save it.</b_a>', 'id', 'Dari berbagai koki dan buku masak, masing-masing mencantumkan penulisnya. Dinilai untuk usia yang Anda pilih. <b_a>Ketuk hati pada resep mana pun untuk menyimpannya.</b_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('From {#} years the ICMR-NIN {#} table is by sex. On the Products and Scan pages, choose boys or girls to score for one of them; with neither chosen the average is used.', 'id', 'Mulai usia {#} tahun tabel ICMR-NIN {#} dibedakan menurut jenis kelamin. Di halaman Produk dan Pindai, pilih anak laki-laki atau perempuan untuk menilai salah satunya; bila tidak memilih keduanya, digunakan rata-ratanya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
