INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('It''s the same thing I was already doing at the shelf, turned into a rubric instead of kept in my head — ten numbers, the age bands they actually apply to, and the citations behind each one. It won''t tell you what to feed your kids. That''s still your call, and it should stay that way. It''ll just tell you, plainly, what''s actually in the pack before you decide.', 'id', 'Ini hal yang sama yang sudah saya lakukan di depan rak, diubah menjadi rubrik, bukan disimpan di kepala — sepuluh angka, kelompok usia yang berlaku, dan kutipan di balik masing-masing. Ini tidak akan memberi tahu Anda apa yang harus diberikan kepada anak Anda. Itu tetap keputusan Anda, dan memang harus begitu. Ini hanya akan memberi tahu Anda, dengan jelas, apa yang sebenarnya ada di dalam kemasan sebelum Anda memutuskan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan features recipes from public recipe sites, with the creator''s name, photo credit and a link back, and steps written in our own words. To ask permission we email the creator at the contact address published on their own site, once. We keep that address, our email, their reply, and a phone number if they choose to send one, only to record their permission and to reach them about sharing. We stop and remove their recipes and photos if they tell us to. Our reader for public pages is described at <a_a>KidPoshanBot</a_a>.', 'id', 'KidPoshan menampilkan resep dari situs resep publik, dengan nama pembuatnya, kredit foto, dan tautan kembali, dan langkah-langkah yang ditulis dengan kata-kata kami sendiri. Untuk meminta izin kami mengirim email sekali kepada pembuatnya di alamat kontak yang dipublikasikan di situs mereka sendiri. Kami menyimpan alamat itu, email kami, balasan mereka, dan nomor telepon bila mereka memilih mengirimkannya, hanya untuk mencatat izin mereka dan menghubungi mereka tentang berbagi. Kami berhenti dan menghapus resep serta foto mereka jika mereka meminta. Pembaca halaman publik kami dijelaskan di <a_a>KidPoshanBot</a_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan helps parents decide what to cook for their children by age, meal and season, and gives every recipe a Poshan Score. This page says what we collect, why, who sees it, and how to have it removed. For anything here, write to <a_a>kidposhan@gmail.com</a_a>.', 'id', 'KidPoshan membantu orang tua memutuskan apa yang dimasak untuk anak mereka menurut usia, waktu makan, dan musim, dan memberi setiap resep sebuah Poshan Score. Halaman ini menjelaskan apa yang kami kumpulkan, mengapa, siapa yang melihatnya, dan bagaimana menghapusnya. Untuk hal apa pun di sini, tulis ke <a_a>kidposhan@gmail.com</a_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan is free for parents. If this recipe helped, ₹', 'id', 'KidPoshan gratis untuk orang tua. Jika resep ini membantu, ₹', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan is written for parents. Children should not give us their details.', 'id', 'KidPoshan ditulis untuk orang tua. Anak-anak tidak boleh memberikan data mereka kepada kami.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
