INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Not out of suspicion at first — more out of habit, the way you check a price tag twice. And the gap between what the front claimed and what the ingredient panel actually said kept showing up in places I didn''t expect. A "wholesome" muesli with sugar sitting a few ingredients down the list. A ketchup where tomato wasn''t even the first thing named. A seasoning sachet whose printed "serving size" was so small that the sodium math only looked reasonable if nobody actually used a full sachet in a meal.', 'id', 'Awalnya bukan karena curiga — lebih karena kebiasaan, seperti memeriksa label harga dua kali. Dan kesenjangan antara apa yang diklaim bagian depan dan apa yang sebenarnya tertulis di panel bahan terus muncul di tempat yang tidak saya duga. Muesli yang "menyehatkan" dengan gula beberapa bahan di bawah dalam daftar. Saus tomat yang tomatnya bahkan bukan hal pertama yang disebut. Sachet bumbu yang "ukuran sajian" tercetaknya begitu kecil sehingga hitungan natriumnya hanya tampak wajar bila tidak ada yang memakai sachet penuh dalam satu hidangan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
