INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Photos you send are kept to score the pack. They may be shown with the pack on the Products page after our team has checked it, so please photograph only the pack, not people. We keep no name, number or address with a scan. See the <a_a>privacy page</a_a>.', 'id', 'Foto yang Anda kirim disimpan untuk menilai kemasan. Foto dapat ditampilkan bersama kemasan di halaman Produk setelah tim kami memeriksanya, jadi mohon foto kemasannya saja, bukan orang. Kami tidak menyimpan nama, nomor, atau alamat bersama pemindaian. Lihat <a_a>halaman privasi</a_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
