INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is a beta built with parents: where the numbers come from, what not yet checked means, and how to add a pack or report a mistake.', 'id', 'Poshan Score adalah beta yang dibuat bersama orang tua: dari mana angkanya berasal, apa arti belum diperiksa, dan cara menambahkan kemasan atau melaporkan kesalahan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
