INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification, and no brand pays to be here. Label values come from the pack''s own page or Open Food Facts. The age guide is general, not medical advice.', 'id', 'Poshan Score adalah penilaian independen, bukan sertifikasi, dan tidak ada merek yang membayar untuk ada di sini. Nilai label berasal dari halaman kemasan itu sendiri atau Open Food Facts. Panduan usia bersifat umum, bukan nasihat medis.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification, and the age guide is general, not medical advice.', 'id', 'Poshan Score adalah penilaian independen, bukan sertifikasi, dan panduan usia bersifat umum, bukan nasihat medis.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
