INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan a pack or paste any recipe link. See its <b_a>real score for your child''s age</b_a>, and how much of what it brags about is actually inside.', 'id', 'Pindai kemasan atau tempel tautan resep apa pun. Lihat <b_a>skor sebenarnya untuk usia anak Anda</b_a>, dan seberapa banyak dari yang dibanggakannya benar-benar ada di dalamnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
