INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan the barcode on any packaged food and see its Poshan Score for your child''s age. If we do not know the pack yet, photograph the front and back and we will score it.', 'id', 'Pindai kode batang pada makanan kemasan apa pun dan lihat Poshan Score-nya untuk usia anak Anda. Jika kami belum mengenal kemasannya, foto bagian depan dan belakang dan kami akan menilainya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan the barcode on any packaged food. If we know the pack you see its Poshan Score straight away. If we do not, photograph the front and the back of the pack and we score it for you, then add it for every parent once our team has checked it.', 'id', 'Pindai kode batang pada makanan kemasan apa pun. Jika kami mengenal kemasan yang Anda lihat, Poshan Score-nya langsung tampil. Jika tidak, foto bagian depan dan belakang kemasan dan kami menilainya untuk Anda, lalu menambahkannya untuk semua orang tua setelah tim kami memeriksanya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
