INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The age groups are the ones the ICMR-NIN {#} table uses: {#}–{#}, {#}–{#} and {#}–{#} years; boys and girls at {#}–{#}, {#}–{#} and {#}–{#}; and adults, men and women at sedentary, moderate or heavy work. Under {#} months we use the {#}–{#} year reference. Tap a group to see its reference numbers. Pregnant and lactating women are not scored yet.', 'id', 'Kelompok usia adalah yang digunakan tabel ICMR-NIN {#}: {#}–{#}, {#}–{#}, dan {#}–{#} tahun; anak laki-laki dan perempuan pada {#}–{#}, {#}–{#}, dan {#}–{#}; serta dewasa, pria dan wanita dengan kerja ringan, sedang, atau berat. Di bawah {#} bulan kami memakai acuan {#}–{#} tahun. Ketuk sebuah kelompok untuk melihat angka acuannya. Ibu hamil dan menyusui belum dinilai.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The aisle', 'id', 'Lorong toko', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The amount of sodium is held constant. Only the age band''s daily reference changes.', 'id', 'Jumlah natrium dijaga tetap. Hanya acuan harian kelompok usia yang berubah.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The barcode could not be read from that photo. Try again with the barcode filling the picture, or type the number under it.', 'id', 'Kode batang tidak dapat dibaca dari foto itu. Coba lagi dengan kode batang memenuhi gambar, atau ketik nomor di bawahnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The barcode reader could not load. Type the number under the barcode instead.', 'id', 'Pembaca kode batang tidak dapat dimuat. Ketik nomor di bawah kode batang sebagai gantinya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The camera could not start. Type the number under the barcode instead, or take a photo of the barcode.', 'id', 'Kamera tidak dapat dimulai. Ketik nomor di bawah kode batang, atau foto kode batangnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The camera is switched off for this page. Allow it in the browser, or type the number under the barcode.', 'id', 'Kamera dimatikan untuk halaman ini. Izinkan di peramban, atau ketik nomor di bawah kode batang.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The camera takes the photo by itself when the picture is sharp and still. You can also tap the button.', 'id', 'Kamera mengambil foto sendiri saat gambar tajam dan diam. Anda juga bisa mengetuk tombolnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
