INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same label can pass at one age and fail at another, so the score out of {#} changes too. Pick the age group on the <a_a>Products page</a_a> and the whole catalogue is re-scored for that age.', 'id', 'Label yang sama bisa lulus pada satu usia dan gagal pada usia lain, sehingga skor dari {#} juga berubah. Pilih kelompok usia di <a_a>halaman Produk</a_a> dan seluruh katalog dinilai ulang untuk usia itu.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same product at each age', 'id', 'Produk yang sama di setiap usia', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same rubric for every product on the shelf — theirs and ours. Ten yes-or-no checks, each worth {#} points, worked out for the age group (and, from {#} years, boy or girl, man or woman) and one realistic serving. Six are numbers off the label, measured against that group''s daily reference. Three are checks on the ingredient list. The tenth fails if the sugar, sodium or saturated-fat check fails. Full citations and thresholds on the <a_a>Age & Metrics</a_a> page.', 'id', 'Rubrik yang sama untuk setiap produk di rak — milik mereka dan milik kami. Sepuluh pemeriksaan ya-atau-tidak, masing-masing bernilai {#} poin, dihitung untuk kelompok usia (dan, mulai usia {#} tahun, laki-laki atau perempuan, pria atau wanita) dan satu sajian yang realistis. Enam adalah angka dari label, diukur terhadap acuan harian kelompok itu. Tiga adalah pemeriksaan daftar bahan. Yang kesepuluh gagal jika pemeriksaan gula, natrium, atau lemak jenuh gagal. Kutipan lengkap dan ambang batas ada di halaman <a_a>Usia & Metrik</a_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The scanner could not load.', 'id', 'Pemindai tidak dapat dimuat.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The site runs on Cloudflare (hosting and database). We use Cloudflare''s AI service to rewrite recipe steps and Tavily to search the web for recipe pages; neither receives your name, number or email. Gmail (Google) is used only as described above. We do not sell or rent your information.', 'id', 'Situs ini berjalan di Cloudflare (hosting dan basis data). Kami menggunakan layanan AI Cloudflare untuk menulis ulang langkah resep dan Tavily untuk mencari halaman resep di web; keduanya tidak menerima nama, nomor, atau email Anda. Gmail (Google) hanya digunakan seperti dijelaskan di atas. Kami tidak menjual atau menyewakan informasi Anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The ten checks, each a yes or no', 'id', 'Sepuluh pemeriksaan, masing-masing ya atau tidak', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The ten checks, the limits for every age group, and how to read the rubric.', 'id', 'Sepuluh pemeriksaan, batas untuk setiap kelompok usia, dan cara membaca rubriknya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The ten marks', 'id', 'Sepuluh nilai', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('There''s enough of that already — inconsistent from one Instagram post to the next, and rarely benchmarked against anything more solid than a personal preference. What I wanted was the same numbers, read the same way, every time, checked against something real — <b_a>ICMR-NIN''s dietary guidelines, FSSAI''s own regulations</b_a> — instead of a brand''s marketing copy. And I wanted our own products held to that same bar, not just everyone else''s on the shelf.', 'id', 'Sudah cukup banyak yang seperti itu — tidak konsisten dari satu unggahan Instagram ke yang berikutnya, dan jarang dibandingkan dengan sesuatu yang lebih kokoh daripada selera pribadi. Yang saya inginkan adalah angka yang sama, dibaca dengan cara yang sama, setiap kali, diperiksa terhadap sesuatu yang nyata — <b_a>pedoman gizi ICMR-NIN, peraturan FSSAI sendiri</b_a> — bukan teks pemasaran sebuah merek. Dan saya ingin produk kami sendiri dituntut dengan standar yang sama, bukan hanya produk orang lain di rak.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('These photos are of a pack I have. I am happy for KidPoshan to show them and use them to score this pack.', 'id', 'Foto-foto ini adalah kemasan yang saya miliki. Saya setuju KidPoshan menampilkannya dan menggunakannya untuk menilai kemasan ini.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('They are saved on this phone now, and nobody else can see them. To open them on another phone or computer, confirm your mobile number with a one-time code. We do not ask for an email.', 'id', 'Resep itu kini tersimpan di ponsel ini, dan tidak ada orang lain yang dapat melihatnya. Untuk membukanya di ponsel atau komputer lain, konfirmasi nomor ponsel Anda dengan kode sekali pakai. Kami tidak meminta email.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This browser cannot use the camera here. Type the number under the barcode instead, or take a photo of the barcode.', 'id', 'Peramban ini tidak dapat memakai kamera di sini. Ketik nomor di bawah kode batang, atau foto kode batangnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This pack', 'id', 'Kemasan ini', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This pack is on the', 'id', 'Kemasan ini ada di', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This photo looks blurred. Please retake it, with the phone steady and the label in good light.', 'id', 'Foto ini tampak buram. Silakan ulangi, dengan ponsel stabil dan label di bawah cahaya yang baik.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This recipe isn''t available.', 'id', 'Resep ini tidak tersedia.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This score is ready to read now. The pack joins the Products page, for every parent, once our team has checked the label.', 'id', 'Skor ini siap dibaca sekarang. Kemasan akan masuk ke halaman Produk, untuk semua orang tua, setelah tim kami memeriksa labelnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This started as a parent''s habit before it became a rubric. Here''s the version without the spreadsheets, the age bands, or the citations.', 'id', 'Ini bermula dari kebiasaan seorang orang tua sebelum menjadi rubrik. Berikut versi tanpa lembar kerja, kelompok usia, atau kutipan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Tick "To buy" on an ingredient and it appears here, grouped under each store.', 'id', 'Centang "Perlu dibeli" pada sebuah bahan dan bahan itu muncul di sini, dikelompokkan menurut toko.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Tick "To buy" on an ingredient to build a shopping list.', 'id', 'Centang "Perlu dibeli" pada sebuah bahan untuk membuat daftar belanja.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
