INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('To send those permission requests and read the replies, KidPoshan connects to the Google account <b_a>kidposhan@gmail.com</b_a> through the Gmail API, with permission only to <b_b>send email</b_b> and to <b_c>read the replies to the emails we sent</b_c>. We do not read any other mail, we do not share Gmail data with anyone, we do not use it for advertising, and it is not used to train any AI model. A reply is read by our systems to record whether the creator agreed and any phone number given, and by the owner of the site. KidPoshan''s use of information received from Google APIs adheres to the <a_d>Google API Services User Data Policy</a_d>, including its Limited Use requirements.', 'id', 'Untuk mengirim permintaan izin itu dan membaca balasannya, KidPoshan terhubung ke akun Google <b_a>kidposhan@gmail.com</b_a> melalui Gmail API, dengan izin hanya untuk <b_b>mengirim email</b_b> dan <b_c>membaca balasan atas email yang kami kirim</b_c>. Kami tidak membaca email lain, kami tidak membagikan data Gmail kepada siapa pun, kami tidak menggunakannya untuk iklan, dan data itu tidak dipakai untuk melatih model AI apa pun. Balasan dibaca oleh sistem kami untuk mencatat apakah pembuat resep setuju dan nomor telepon yang diberikan, serta oleh pemilik situs. Penggunaan informasi yang diterima KidPoshan dari Google APIs mematuhi <a_d>Google API Services User Data Policy</a_d>, termasuk persyaratan Limited Use-nya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
