INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Under {#} months there is no published reference band, so the <b_a>{#}–{#} years</b_a> reference numbers are used. Only plain foods meant for babies are scored: a product with added sugar or salt is shown as “Not for under {#}”, not as a number.', 'id', 'Di bawah {#} bulan tidak ada rentang acuan yang dipublikasikan, jadi angka acuan <b_a>{#}–{#} tahun</b_a> digunakan. Hanya makanan polos untuk bayi yang dinilai: produk dengan gula atau garam tambahan ditampilkan sebagai “Tidak untuk usia di bawah {#}”, bukan sebagai angka.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
