INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We are still adding packs. If yours is missing, scan it and we will score it from your photos.', 'id', 'Kami masih menambahkan kemasan. Jika kemasan Anda belum ada, pindai dan kami akan menilainya dari foto Anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We confirm each payment against our UPI account before counting it. Payment is optional and does not unlock anything.', 'id', 'Kami mengonfirmasi setiap pembayaran pada akun UPI kami sebelum menghitungnya. Pembayaran bersifat opsional dan tidak membuka apa pun.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
