INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We keep no name or phone number with a scan or a report. More is on the <a_a>privacy page</a_a>.', 'id', 'Kami tidak menyimpan nama atau nomor telepon bersama pemindaian atau laporan. Selengkapnya ada di <a_a>halaman privasi</a_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We keep what you give us for as long as the site runs, or until you ask us to delete it. You can ask us to show you, correct or delete your name, number, email, ratings or remarks, or a creator''s details, by writing to <a_a>kidposhan@gmail.com</a_a>. We will deal with it promptly.', 'id', 'Kami menyimpan apa yang Anda berikan selama situs berjalan, atau sampai Anda meminta kami menghapusnya. Anda dapat meminta kami menunjukkan, memperbaiki, atau menghapus nama, nomor, email, penilaian, atau komentar Anda, atau data pembuat resep, dengan menulis ke <a_a>kidposhan@gmail.com</a_a>. Kami akan menanganinya segera.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We use these to know who rated or wrote a remark. Your mobile number is never shown on the site.', 'id', 'Kami menggunakan ini untuk mengetahui siapa yang menilai atau menulis komentar. Nomor ponsel Anda tidak pernah ditampilkan di situs.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
