INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('When we are wrong, we want to hear it. Every pack has a <b_a>Report a mistake</b_a> button.', 'id', 'Saat kami salah, kami ingin mendengarnya. Setiap kemasan memiliki tombol <b_a>Laporkan kesalahan</b_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('When you send photos you tick a box to say they are of a pack you have and that KidPoshan may show them and use them to score the pack. Please photograph only the pack, not people.', 'id', 'Saat mengirim foto Anda mencentang kotak yang menyatakan bahwa foto itu dari kemasan yang Anda miliki dan bahwa KidPoshan boleh menampilkannya serta menggunakannya untuk menilai kemasan tersebut. Mohon foto kemasannya saja, bukan orang.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
