INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no Class II preservative is named in the ingredients: the ones parents recognise least, checked most.', 'id', 'Ya jika tidak ada pengawet Kelas II yang disebut dalam bahan: yang paling tidak dikenal orang tua, paling sering diperiksa.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no artificial colour, flavour enhancer or sweetener is named, by INS number or by name.', 'id', 'Ya jika tidak ada pewarna buatan, penguat rasa, atau pemanis yang disebut, menurut nomor INS atau nama.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no hydrogenated oil, vanaspati or margarine is listed. FSSAI caps industrial trans fat at {#}% of oils and fats, the same at every age.', 'id', 'Ya jika tidak ada minyak terhidrogenasi, vanaspati, atau margarin yang tercantum. FSSAI membatasi lemak trans industri hingga {#}% dari minyak dan lemak, sama untuk setiap usia.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving gives at least {#}% of the day''s fibre for that age group, from ICMR-NIN {#}.', 'id', 'Ya jika satu sajian memberi paling sedikit {#}% serat harian untuk kelompok usia itu, dari ICMR-NIN {#}.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving gives at least {#}% of the day''s protein for that age group, sex and kind of work, from the ICMR-NIN {#} RDAs.', 'id', 'Ya jika satu sajian memberi paling sedikit {#}% protein harian untuk kelompok usia, jenis kelamin, dan jenis pekerjaan itu, dari AKG ICMR-NIN {#}.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s free-sugar limit for that age group ({#}% for snacks and sweets). The limit is {#}% of energy, from WHO, on ICMR-NIN energy.', 'id', 'Ya jika satu sajian tetap di bawah {#}% batas gula bebas harian untuk kelompok usia itu ({#}% untuk camilan dan makanan manis). Batasnya adalah {#}% energi, dari WHO, pada energi ICMR-NIN.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s limit ({#}% for snacks and sweets). The limit is WHO''s under {#}% of energy.', 'id', 'Ya jika satu sajian tetap di bawah {#}% batas harian ({#}% untuk camilan dan makanan manis). Batasnya adalah batas WHO di bawah {#}% energi.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s sodium ({#}% for snacks and sweets). ICMR-NIN''s adult limit is {#} mg; for children we scale it down by energy.', 'id', 'Ya jika satu sajian tetap di bawah {#}% natrium harian ({#}% untuk camilan dan makanan manis). Batas dewasa ICMR-NIN adalah {#} mg; untuk anak kami menurunkannya menurut energi.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if the first ingredient is a real food, not sugar or a refined flour, starch or fat.', 'id', 'Ya jika bahan pertama adalah makanan asli, bukan gula atau tepung, pati, atau lemak olahan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes only if the sugar, sodium and saturated-fat checks all pass. Echoes FSSAI''s pending front-of-pack warning for foods high in fat, sugar or salt.', 'id', 'Ya hanya jika pemeriksaan gula, natrium, dan lemak jenuh semuanya lulus. Mengikuti peringatan depan kemasan FSSAI yang masih diusulkan untuk makanan tinggi lemak, gula, atau garam.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Your email is optional. If you leave it, we use it once, to thank you when your pack is checked, or to tell you what we did about a report. We use it for nothing else, and we do not share it.', 'id', 'Email Anda opsional. Jika Anda mengisinya, kami menggunakannya sekali, untuk berterima kasih saat kemasan Anda diperiksa, atau memberi tahu apa yang kami lakukan atas sebuah laporan. Kami tidak menggunakannya untuk hal lain, dan kami tidak membagikannya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
