INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('{#} kids'' recipes from cooks and cookbooks, each with a Poshan Score for every age from toddlers to adults. Breakfast, lunchbox, lunch, snacks and dinner, vegetarian, Jain and non-vegetarian.', 'id', '{#} resep anak dari koki dan buku masak, masing-masing dengan Poshan Score untuk setiap usia dari balita sampai dewasa. Sarapan, bekal, makan siang, camilan, dan makan malam, vegetarian, Jain, dan non-vegetarian.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('{#} recipes from various cooks and cookbooks, each credited to the person who wrote it. Every recipe has a Poshan Score out of {#}, worked out for one serving and for every age group from toddlers to adults. Open one to see the ingredients and the score for your child''s age, save it, and plan your week.', 'id', '{#} resep dari berbagai koki dan buku masak, masing-masing mencantumkan penulisnya. Setiap resep memiliki Poshan Score dari {#}, dihitung untuk satu sajian dan untuk setiap kelompok usia dari balita sampai dewasa. Buka satu untuk melihat bahan dan skor untuk usia anak Anda, simpan, dan susun rencana seminggu Anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
