INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('" yet. We are adding the best-known kids'' foods first, and what you search for helps us choose. Try one word, like "oats" or "ragi".', 'ms', '" lagi. Kami menambah makanan kanak-kanak yang paling terkenal dahulu, dan apa yang anda cari membantu kami memilih. Cuba satu perkataan, seperti "oat" atau "ragi".', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
