INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('"The label wasn''t lying. It just wasn''t written for someone standing in an aisle with fifteen seconds and a tired kid."', 'ms', 'Label itu tidak berbohong. Cuma ia tidak ditulis untuk orang yang berdiri di lorong kedai dengan masa lima belas saat dan anak yang penat.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
