INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('. Scores are for that age. Best score first, among the ones that fit.', 'ms', '. Skor adalah untuk umur itu. Skor terbaik dahulu, antara yang sesuai.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('. Thank you for helping us get it right.', 'ms', '. Terima kasih kerana membantu kami mendapatkannya dengan betul.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('. The score comes from the nutrition table and the ingredients on your back photo.', 'ms', '. Skor datang daripada jadual pemakanan dan senarai bahan pada foto belakang pek anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('. Try leaving out the taste or the meal, or a different age.', 'ms', '. Cuba tanpa citarasa atau waktu makan tertentu, atau pilih umur lain.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<a_a>Home</a_a> › Compare', 'ms', '<a_a>Laman Utama</a_a> › Bandingkan', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<a_a>Home</a_a> › Recipes', 'ms', '<a_a>Laman Utama</a_a> › Resipi', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<a_a>See every recipe</a_a>, each with its own page and score, or <a_b>browse ideas by taste, meal and age</a_b>.', 'ms', '<a_a>Lihat semua resipi</a_a>, setiap satu dengan laman dan skornya sendiri, atau <a_b>layari idea mengikut citarasa, waktu makan dan umur</a_b>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>A random id kept in your browser</b_a> (no name, number or IP address is stored with it). It lets us count how many different browsers visit and show you recipes you have not seen yet when you repeat a search. Your browser also keeps your chosen filters, shopping ticks and login token on your device. We do not use advertising or tracking cookies.', 'ms', '<b_a>Kod rawak yang disimpan dalam pelayar anda</b_a> (tiada nama, nombor atau alamat IP disimpan bersamanya). Ia membolehkan kami mengira berapa banyak pelayar berbeza yang melawat dan menunjukkan resipi yang belum anda lihat apabila anda mengulang carian. Pelayar anda juga menyimpan penapis pilihan, tanda beli-belah dan token log masuk pada peranti anda. Kami tidak menggunakan kuki pengiklanan atau penjejakan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Hundreds of</b_a> recipes, by age, meal, season and food preference. Save the ones you like, then put them into a plan for the week: breakfast, lunch, a {#} PM snack and dinner, for every day.', 'ms', '<b_a>Beratus-ratus</b_a> resipi, mengikut umur, waktu makan, musim dan pilihan makanan. Simpan yang anda suka, kemudian susun menjadi pelan seminggu: sarapan, makan tengah hari, snek pukul {#} petang dan makan malam, untuk setiap hari.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Is this your pack?</b_a> On a pack that is not yet checked, tell us if the name on your pack is different. Then photograph yours, and it is scored from your photos.', 'ms', '<b_a>Adakah ini pek anda?</b_a> Pada pek yang belum disemak, beritahu kami jika nama pada pek anda berbeza. Kemudian ambil foto pek anda, dan ia diberi skor daripada foto anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Mistake reports and your optional email.</b_a> If you report a mistake on a pack, we keep what you wrote and the pack it is about. If you leave an email (with a report or with photos), we use it once, to thank you when the pack is checked or to tell you what we did, and for nothing else. Leaving it is always optional. When you send photos you tick a box to say they are of a pack you have and that KidPoshan may show them and use them to score the pack.', 'ms', '<b_a>Laporan kesilapan dan e-mel pilihan anda.</b_a> Jika anda melaporkan kesilapan pada sesuatu pek, kami menyimpan apa yang anda tulis dan pek yang berkenaan. Jika anda memberi e-mel (bersama laporan atau foto), kami menggunakannya sekali, untuk berterima kasih apabila pek disemak atau memberitahu apa yang kami lakukan, dan bukan untuk apa-apa lagi. Memberinya sentiasa pilihan. Apabila anda menghantar foto, anda menanda kotak untuk menyatakan foto itu ialah pek yang anda miliki dan KidPoshan boleh menunjukkannya serta menggunakannya untuk memberi skor kepada pek itu.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Name, mobile number and email address</b_a>, only if you give them (when you rate a recipe, send a remark, or fill in the small "Join KidPoshan" box on a recipe page). We use them to know who rated a recipe or wrote a remark. We do not check that a number or address is yours. Your mobile number and email are <b_b>never shown</b_b> on the site. Your name is shown only next to a remark that our team has approved.', 'ms', '<b_a>Nama, nombor telefon bimbit dan alamat e-mel</b_a>, hanya jika anda memberikannya (apabila anda menilai resipi, menghantar komen, atau mengisi kotak kecil "Sertai KidPoshan" pada laman resipi). Kami menggunakannya untuk mengetahui siapa yang menilai resipi atau menulis komen. Kami tidak menyemak sama ada nombor atau alamat itu milik anda. Nombor telefon bimbit dan e-mel anda <b_b>tidak pernah dipaparkan</b_b> di laman ini. Nama anda hanya dipaparkan di sebelah komen yang telah diluluskan oleh pasukan kami.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Open Food Facts</b_a>, a free database of food products made by people around the world (<a_b>openfoodfacts.org</a_b>, Open Database Licence). We credit it on every page that uses it.', 'ms', '<b_a>Open Food Facts</b_a>, pangkalan data percuma produk makanan yang dibuat oleh orang di seluruh dunia (<a_b>openfoodfacts.org</a_b>, Open Database Licence). Kami memberi kredit kepadanya pada setiap laman yang menggunakannya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Optional ₹{#} support.</b_a> You pay in your own UPI app; we never see your bank or card details. If you tell us you have paid, we keep the amount, the time and the payment reference you typed, so we can confirm it.', 'ms', '<b_a>Sokongan pilihan ₹{#}.</b_a> Anda membayar melalui aplikasi UPI anda sendiri; kami tidak pernah melihat butiran bank atau kad anda. Jika anda memberitahu kami anda telah membayar, kami menyimpan jumlah, masa dan rujukan pembayaran yang anda taip, supaya kami boleh mengesahkannya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Packs you scan.</b_a> When you scan a barcode we look the pack up. If you send photos of a pack, we keep the barcode and the two photos, and read the nutrition label from the back photo. The photos may be shown with the pack on the Products page after our team has checked it, so please photograph only the pack and not people. We keep no name, number or address with a scan. To stop one phone sending too many, we keep a one-day code made from your connection (not your IP address) for two days.', 'ms', '<b_a>Pek yang anda imbas.</b_a> Apabila anda mengimbas kod bar, kami mencari pek itu. Jika anda menghantar foto sesuatu pek, kami menyimpan kod bar dan dua foto, dan membaca label pemakanan daripada foto belakang. Foto itu mungkin dipaparkan bersama pek di laman Produk selepas pasukan kami menyemaknya, jadi sila ambil foto pek sahaja dan bukan orang. Kami tidak menyimpan nama, nombor atau alamat bersama imbasan. Untuk menghalang satu telefon menghantar terlalu banyak, kami menyimpan kod satu hari yang dibuat daripada sambungan anda (bukan alamat IP anda) selama dua hari.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Photos from parents:</b_a> the front and back of a pack. Our label reader reads the table, and our team checks the numbers against the photo before a pack is marked checked.', 'ms', '<b_a>Foto daripada ibu bapa:</b_a> bahagian hadapan dan belakang pek. Pembaca label kami membaca jadualnya, dan pasukan kami menyemak nombor itu dengan foto sebelum pek ditandakan sudah disemak.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Ratings and remarks</b_a> you submit. A remark appears on the site only after our team approves it, and you can ask us to remove it.', 'ms', '<b_a>Penilaian dan komen</b_a> yang anda hantar. Komen hanya muncul di laman ini selepas pasukan kami meluluskannya, dan anda boleh meminta kami mengalihkannya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Report a mistake</b_a> on any pack: a wrong name, numbers that do not match the label, or a wrong photo.', 'ms', '<b_a>Laporkan kesilapan</b_a> pada mana-mana pek: nama yang salah, nombor yang tidak sepadan dengan label, atau foto yang salah.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Saved recipes and your weekly plan</b_a> stay on your phone. Only if you choose to use them on another device do we ask for your mobile number and a one-time code sent by SMS; the saved list is then stored under that verified number so nobody else can open it.', 'ms', '<b_a>Resipi tersimpan dan pelan mingguan anda</b_a> kekal pada telefon anda. Hanya jika anda memilih untuk menggunakannya pada peranti lain, kami meminta nombor telefon bimbit anda dan kod sekali guna melalui SMS; senarai tersimpan itu kemudian disimpan di bawah nombor yang disahkan itu supaya tiada orang lain boleh membukanya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Scan a pack</b_a> we do not have, and photograph its front and back.', 'ms', '<b_a>Imbas pek</b_a> yang belum ada pada kami, dan ambil foto bahagian hadapan dan belakangnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>The pack''s own label:</b_a> the nutrition table and the ingredient list, per {#} g, as printed.', 'ms', '<b_a>Label pek itu sendiri:</b_a> jadual pemakanan dan senarai bahan, setiap {#} g, seperti yang dicetak.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>What is a citation and what is our own judgment:</b_a> the daily references behind checks {#}, {#}, {#}, {#} and {#} come from [{#}] to [{#}], except the child sodium limit, which is our scaling of [{#}] (see [{#}]). Checks {#}, {#} and {#} test the ingredient list against FSSAI rules [{#}] and [{#}]. Check {#} echoes the high-in-fat-sugar-or-salt idea in [{#}], but the rule itself is ours. These parts are our own choices, applied the same way every time: the line a serving must stay under ({#}% of the day, {#}% for snacks, sweets and sweet drinks) to pass sugar, sodium and saturated fat; the {#}% of the day a serving must give to pass fibre and protein; the base-ingredient check ({#}); which foods count as snacks; and holding a pack at OK when a risk check fails. The {#}% line is also the one the UK''s traffic-light labels use for a portion. Under {#} months there is no published reference band, so the {#} to {#} year reference is used. Pregnant and lactating women and the elderly are not scored yet.', 'ms', '<b_a>Apa yang petikan dan apa yang pertimbangan kami sendiri:</b_a> rujukan harian di sebalik semakan {#}, {#}, {#}, {#} dan {#} datang daripada [{#}] hingga [{#}], kecuali had natrium kanak-kanak, iaitu penskalaan kami terhadap [{#}] (lihat [{#}]). Semakan {#}, {#} dan {#} menguji senarai bahan terhadap peraturan FSSAI [{#}] dan [{#}]. Semakan {#} menyerupai idea tinggi-lemak-gula-atau-garam dalam [{#}], tetapi peraturannya sendiri ialah milik kami. Bahagian ini ialah pilihan kami sendiri, digunakan dengan cara yang sama setiap kali: garis yang tidak boleh dilepasi satu sajian ({#}% daripada keperluan sehari, {#}% untuk snek, manisan dan minuman manis) untuk lulus gula, natrium dan lemak tepu; {#}% daripada keperluan sehari yang mesti diberi satu sajian untuk lulus serat dan protein; semakan bahan asas ({#}); makanan mana yang dikira snek; dan menahan pek pada Sederhana apabila satu semakan risiko gagal. Garis {#}% juga ialah garis yang digunakan label lampu isyarat UK untuk satu hidangan. Di bawah {#} bulan tiada julat rujukan diterbitkan, jadi rujukan umur {#} hingga {#} tahun digunakan. Wanita hamil dan menyusu serta warga emas belum diberi skor.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Which pages are opened and for how long.</b_a> For each page view we keep the page, the time, how long it stayed on screen, and the country and city your connection appears to be in. We do not keep your IP address. This is only for our own anonymous visit statistics; crawlers and monitors are not counted as visitors, and these records are deleted after about {#} months.', 'ms', '<b_a>Laman mana yang dibuka dan berapa lama.</b_a> Bagi setiap paparan laman kami menyimpan laman itu, masanya, berapa lama ia kekal pada skrin, serta negara dan bandar tempat sambungan anda kelihatan berada. Kami tidak menyimpan alamat IP anda. Ini hanya untuk statistik lawatan tanpa nama kami sendiri; perangkak dan monitor tidak dikira sebagai pelawat, dan rekod ini dipadam selepas kira-kira {#} bulan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Your email address and your choices, for the weekly tiffin email</b_a>, only if you sign up at <a_b>kidposhan.in/newsletter</a_b>: the address, your child''s age group and food preference, and when you agreed. We send a first email to confirm it is yours, and nothing more until you confirm. Every email has a one-click unsubscribe link, and after you unsubscribe we send nothing. Your address is used only for this email and is not shared. To have it deleted, write to <a_c>kidposhan@gmail.com</a_c>.', 'ms', '<b_a>Alamat e-mel dan pilihan anda, untuk e-mel bekal mingguan</b_a>, hanya jika anda mendaftar di <a_b>kidposhan.in/newsletter</a_b>: alamatnya, kumpulan umur dan pilihan makanan anak anda, serta bila anda bersetuju. Kami menghantar e-mel pertama untuk mengesahkan alamat itu milik anda, dan tiada apa-apa lagi sehingga anda mengesahkan. Setiap e-mel mempunyai pautan henti langganan satu klik, dan selepas anda berhenti kami tidak menghantar apa-apa. Alamat anda hanya digunakan untuk e-mel ini dan tidak dikongsi. Untuk memadamnya, tulis kepada <a_c>kidposhan@gmail.com</a_c>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI compliance affidavit, Supreme Court of India, W.P.(C) No. {#}/{#} — {#}S and Our Health Society vs Union of India, filed {#} August {#}.</b_a> Proposes a front-of-pack red hexagon warning for foods high in added saturated fat, added sugar, and/or salt (HFSS), with thresholds to be drawn from the <i_b>Dietary Guidelines for Indians, {#}</i_b> (ICMR-NIN). This is a live, pending proceeding — not yet a notified regulation.', 'ms', '<b_a>[{#}] Afidavit pematuhan FSSAI, Mahkamah Agung India, W.P.(C) No. {#}/{#} — {#}S and Our Health Society vs Union of India, difailkan {#} Ogos {#}.</b_a> Mencadangkan amaran heksagon merah di hadapan pek untuk makanan tinggi lemak tepu tambahan, gula tambahan dan/atau garam (HFSS), dengan ambang yang diambil daripada <i_b>Dietary Guidelines for Indians, {#}</i_b> (ICMR-NIN). Ini ialah prosiding yang masih berjalan, bukan peraturan yang telah diwartakan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI, Food Safety and Standards (Food Products Standards and Food Additives) Regulations, {#}.</b_a> Governs permitted preservatives (Class II) and additives (colours, flavour enhancers) by INS number.', 'ms', '<b_a>[{#}] FSSAI, Food Safety and Standards (Food Products Standards and Food Additives) Regulations, {#}.</b_a> Mengawal pengawet yang dibenarkan (Kelas II) dan bahan tambah (pewarna, penguat perisa) mengikut nombor INS.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI, Food Safety and Standards (Prohibition and Restrictions on Sales) Regulations.</b_a> Trans fat capped at ≤{#}% of total oils and fats in any food product, all ages, all categories.', 'ms', '<b_a>[{#}] FSSAI, Food Safety and Standards (Prohibition and Restrictions on Sales) Regulations.</b_a> Lemak trans dihadkan kepada ≤{#}% daripada jumlah minyak dan lemak dalam sebarang produk makanan, semua umur, semua kategori.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] ICMR-NIN (National Institute of Nutrition), "Nutrient Requirements for Indians: Recommended Dietary Allowances and Estimated Average Requirements," {#}.</b_a> The source for the energy requirement, protein RDA and dietary fibre RDA of every group on this page: children {#}–{#}, {#}–{#} and {#}–{#}; boys and girls {#}–{#}, {#}–{#} and {#}–{#}; men and women at sedentary, moderate and heavy work. It also gives the adult sodium limit of {#} mg a day ({#} g of salt), which it takes from WHO ({#}).', 'ms', '<b_a>[{#}] ICMR-NIN (National Institute of Nutrition), "Nutrient Requirements for Indians: Recommended Dietary Allowances and Estimated Average Requirements," {#}.</b_a> Sumber bagi keperluan tenaga, RDA protein dan RDA serat makanan bagi setiap kumpulan di laman ini: kanak-kanak {#}–{#}, {#}–{#} dan {#}–{#}; budak lelaki dan perempuan {#}–{#}, {#}–{#} dan {#}–{#}; lelaki dan wanita pada kerja ringan, sederhana dan berat. Ia juga memberi had natrium dewasa {#} mg sehari ({#} g garam), yang diambilnya daripada WHO ({#}).', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] Serving sizes.</b_a> The serving printed on the pack. Where a pack prints none, a reference amount for that kind of food, taken from the US FDA''s "reference amounts customarily consumed" ({#} CFR {#}) where one fits, and our own estimate where none does.', 'ms', '<b_a>[{#}] Saiz sajian.</b_a> Sajian yang dicetak pada pek. Jika pek tidak mencetaknya, jumlah rujukan bagi jenis makanan itu digunakan, diambil daripada "reference amounts customarily consumed" US FDA ({#} CFR {#}) jika ada yang sesuai, dan anggaran kami sendiri jika tiada.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO guidance on saturated fat</b_a> (the {#} guideline on saturated and trans fatty acid intake, and the FAO/WHO fats consultations). Saturated fat under {#}% of energy, converted to grams at {#} kcal/g.', 'ms', '<b_a>[{#}] Panduan WHO tentang lemak tepu</b_a> (garis panduan {#} tentang pengambilan asid lemak tepu dan trans, serta perundingan FAO/WHO tentang lemak). Lemak tepu kurang daripada {#}% tenaga, ditukar kepada gram pada {#} kkal/g.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO, "Guideline: Sodium intake for adults and children," {#}.</b_a> For children the adult limit is lowered in line with their lower energy needs. ICMR-NIN {#} gives no child figure, so we apply that rule ourselves: the {#} mg adult limit scaled by each group''s energy, about {#} mg per kcal, never above {#} mg. These child limits are our calculation, not a published figure.', 'ms', '<b_a>[{#}] WHO, "Guideline: Sodium intake for adults and children," {#}.</b_a> Bagi kanak-kanak had dewasa diturunkan selaras dengan keperluan tenaga mereka yang lebih rendah. ICMR-NIN {#} tidak memberi angka kanak-kanak, jadi kami menggunakan peraturan itu sendiri: had dewasa {#} mg diskalakan mengikut tenaga setiap kumpulan, kira-kira {#} mg setiap kkal, tidak pernah melebihi {#} mg. Had kanak-kanak ini ialah pengiraan kami, bukan angka yang diterbitkan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO, "Guideline: Sugars intake for adults and children," {#}.</b_a> Free sugars under {#}% of energy, with further benefit below {#}%. We use {#}% of each group''s energy as the daily ideal and {#}% as the upper limit, converted to grams at {#} kcal/g.', 'ms', '<b_a>[{#}] WHO, "Guideline: Sugars intake for adults and children," {#}.</b_a> Gula bebas kurang daripada {#}% tenaga, dengan manfaat tambahan di bawah {#}%. Kami menggunakan {#}% daripada tenaga setiap kumpulan sebagai ideal harian dan {#}% sebagai had atas, ditukar kepada gram pada {#} kkal/g.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>{#} m–adult</b_a><span_b>every score worked out for the age group</span_b>', 'ms', '<b_a>{#} bln–dewasa</b_a><span_b>setiap skor dikira untuk kumpulan umur</span_b>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
