INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification · No brand pays to be here', 'ms', 'Dipadankan dengan <b_a>ICMR-NIN {#}</b_a> dan <b_b>FSSAI</b_b> · Poshan Score ialah penilaian bebas, bukan pensijilan · Tiada jenama membayar untuk berada di sini', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Dish photos belong to their creators and link back to the original recipe. Pack photos are the sellers''.', 'ms', 'Dipadankan dengan <b_a>ICMR-NIN {#}</b_a> dan <b_b>FSSAI</b_b> · Poshan Score ialah penilaian bebas, bukan pensijilan<br_c/> Foto hidangan milik pembuatnya dan memaut kembali ke resipi asal. Foto pek milik penjual.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Label data may come from <a_d>Open Food Facts</a_d> contributors (Open Database Licence) or from photos sent by parents and read by our label reader, and is checked before a pack is listed. The age guide is general and cautious. It is not medical advice.', 'ms', 'Dipadankan dengan <b_a>ICMR-NIN {#}</b_a> dan <b_b>FSSAI</b_b> · Poshan Score ialah penilaian bebas, bukan pensijilan<br_c/> Data label mungkin datang daripada penyumbang <a_d>Open Food Facts</a_d> (Open Database Licence) atau daripada foto yang dihantar ibu bapa dan dibaca oleh pembaca label kami, dan disemak sebelum pek disenaraikan. Panduan umur bersifat umum dan berhati-hati. Ia bukan nasihat perubatan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Pack photos are the sellers'' or, where marked, from <a_d>Open Food Facts</a_d> contributors (CC BY-SA). Some label data comes from Open Food Facts under the Open Database Licence. The age guide is general and cautious. It is not medical advice.', 'ms', 'Dipadankan dengan <b_a>ICMR-NIN {#}</b_a> dan <b_b>FSSAI</b_b> · Poshan Score ialah penilaian bebas, bukan pensijilan<br_c/> Foto pek milik penjual atau, jika ditandakan, daripada penyumbang <a_d>Open Food Facts</a_d> (CC BY-SA). Sebahagian data label datang daripada Open Food Facts di bawah Open Database Licence. Panduan umur bersifat umum dan berhati-hati. Ia bukan nasihat perubatan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a>, <b_b>WHO</b_b> guidance and <b_c>FSSAI</b_c> regulation · Poshan Score is an independent rating, not a certification', 'ms', 'Dipadankan dengan <b_a>ICMR-NIN {#}</b_a>, panduan <b_b>WHO</b_b> dan peraturan <b_c>FSSAI</b_c> · Poshan Score ialah penilaian bebas, bukan pensijilan', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
