INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Each check below shows exactly what earns a yes and what earns a no. Count the yeses and multiply by {#} to get the score from {#} to {#}. This is why we do not trust the front of the pack: watch what is printed there against what is actually on the back.', 'ms', 'Setiap semakan di bawah menunjukkan dengan tepat apa yang mendapat ya dan apa yang mendapat tidak. Kira bilangan ya dan darabkan dengan {#} untuk mendapat skor daripada {#} hingga {#}. Inilah sebabnya kami tidak mempercayai bahagian hadapan pek: lihat apa yang dicetak di sana berbanding apa yang sebenarnya ada di belakang.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Energy kcal', 'ms', 'Tenaga kkal', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Energy, protein and fibre are the ICMR-NIN {#} figures for each group (energy is NIN''s estimated requirement). Added sugar is {#}% of energy (upper {#}%) and saturated fat {#}% of energy (WHO). Sodium is the ICMR-NIN {#} adult limit of {#} mg, scaled down by energy for younger children. The row without a sex is the average of the two.', 'ms', 'Tenaga, protein dan serat ialah angka ICMR-NIN {#} bagi setiap kumpulan (tenaga ialah anggaran keperluan NIN). Gula tambahan ialah {#}% tenaga (had atas {#}%) dan lemak tepu {#}% tenaga (WHO). Natrium ialah had dewasa ICMR-NIN {#} sebanyak {#} mg, diturunkan mengikut tenaga untuk kanak-kanak yang lebih kecil. Baris tanpa jantina ialah purata kedua-duanya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Estimated from the ingredient list: each ingredient is weighed, and the sugar, salt, saturated fat, fibre and protein of one serving are added up.', 'ms', 'Dianggarkan daripada senarai bahan: setiap bahan ditimbang, dan gula, garam, lemak tepu, serat dan protein bagi satu sajian dijumlahkan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every number on this page, sourced', 'ms', 'Setiap nombor di laman ini, lengkap dengan sumbernya', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every pack says <em_a>healthy.</em_a><br_b/>Every recipe says <em_c>wholesome.</em_c><br_d/><span_e>We read what is really inside.</span_e>', 'ms', 'Setiap pek mendakwa ia <em_a>sihat.</em_a><br_b/>Setiap resipi mendakwa ia <em_c>berkhasiat.</em_c><br_d/><span_e>Kami membaca apa yang benar-benar ada di dalamnya.</span_e>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every pack says it is healthy. We read the back. Poshan Score is a beta, and it gets better each time a parent adds a pack or corrects one.', 'ms', 'Setiap pek mendakwa ia sihat. Kami membaca bahagian belakang. Poshan Score ialah beta, dan ia bertambah baik setiap kali seorang ibu atau bapa menambah pek atau membetulkannya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product and every recipe gets <b_a>one score from {#} to {#}</b_a>. Each of the ten checks is a plain <b_b>yes ({#}) or no ({#})</b_b>, and the score is the number passed times {#}, so a product that passes everything scores exactly {#} and one that passes nothing scores {#}. Six of them are numbers off the label, measured as a share of the daily reference for the age group (and, from {#} years, the sex and kind of work): <b_c>added sugar, sodium, saturated fat, trans fat, fibre and protein</b_c>. Fibre and protein are <b_d>credit</b_d> metrics (more is better); the others are <b_e>risk</b_e> metrics (less is better). Three more are checks that do not change with age: <b_f>preservatives, artificial additives and base-ingredient integrity</b_f>. The tenth is <b_g>HFSS</b_g>, which fails if the sugar, sodium or saturated-fat check fails. A product that fails any one risk check is held at <b_h>OK</b_h>: the score still shows the real count, with a "capped" badge. Packs and recipes are scored the same way, per realistic serving, so they can be compared. The same method is used on the Products and Meal Ideas pages. Every number below is cited, and the sources are listed at the bottom of this page.', 'ms', 'Setiap produk dan setiap resipi mendapat <b_a>satu skor daripada {#} hingga {#}</b_a>. Setiap satu daripada sepuluh semakan ialah <b_b>ya ({#}) atau tidak ({#})</b_b> yang jelas, dan skornya ialah bilangan yang lulus didarab {#}, jadi produk yang lulus semuanya mendapat tepat {#} dan yang tidak lulus satu pun mendapat {#}. Enam daripadanya ialah nombor pada label, diukur sebagai bahagian daripada rujukan harian bagi kumpulan umur (dan, mulai {#} tahun, jantina dan jenis kerja): <b_c>gula tambahan, natrium, lemak tepu, lemak trans, serat dan protein</b_c>. Serat dan protein ialah metrik <b_d>kredit</b_d> (lebih banyak lebih baik); yang lain ialah metrik <b_e>risiko</b_e> (lebih sedikit lebih baik). Tiga lagi ialah semakan yang tidak berubah mengikut umur: <b_f>pengawet, bahan tambah tiruan dan integriti bahan asas</b_f>. Yang kesepuluh ialah <b_g>HFSS</b_g>, yang gagal jika semakan gula, natrium atau lemak tepu gagal. Produk yang gagal pada mana-mana satu semakan risiko ditahan pada <b_h>Sederhana</b_h>: skor masih menunjukkan bilangan sebenar, dengan lencana "dihadkan". Pek dan resipi diberi skor dengan cara yang sama, bagi setiap sajian yang realistik, supaya boleh dibandingkan. Kaedah yang sama digunakan di laman Produk dan Idea Hidangan. Setiap nombor di bawah dipetik, dan sumbernya disenaraikan di bahagian bawah laman ini.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product below gets a Poshan Score out of {#}, from the nutrition label printed on the pack, worked out for one realistic serving (the same way recipes are scored, so the two can be compared). The score is made of ten yes-or-no checks, each worth {#} points, and it is worked out for the age you pick. A low score is not a warning. It is a reason to keep it occasional. We search for new products every few hours and read their labels, and a product appears here once its label has been read and checked.', 'ms', 'Setiap produk di bawah mendapat Poshan Score daripada {#}, berdasarkan label pemakanan yang dicetak pada pek, dikira bagi satu sajian yang realistik (dengan cara yang sama resipi diberi skor, supaya keduanya boleh dibandingkan). Skor itu terdiri daripada sepuluh semakan ya-atau-tidak, setiap satu bernilai {#} mata, dan dikira untuk umur yang anda pilih. Skor rendah bukan amaran. Ia sebab untuk memberinya sesekali sahaja. Kami mencari produk baharu setiap beberapa jam dan membaca labelnya, dan sesuatu produk muncul di sini setelah labelnya dibaca dan disemak.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product we rate is scored on ten yes-or-no checks, for every age group from {#} months to adults: children, boys and girls, men and women.', 'ms', 'Setiap produk yang kami nilai diberi skor pada sepuluh semakan ya-atau-tidak, bagi setiap kumpulan umur dari {#} bulan hingga dewasa: kanak-kanak, budak lelaki dan perempuan, lelaki dan wanita.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Everything I kept finding was printed, in compliance with the law, in the correct font size. This wasn''t a story about brands breaking rules — it was a story about how much a food label can get away with saying, technically, truthfully, while still leaving a parent with the wrong picture of what''s actually going into their child. <b_a>The rules were being followed. The point was still being missed.</b_a>', 'ms', 'Semua yang saya terus jumpa dicetak, mengikut undang-undang, dalam saiz fon yang betul. Ini bukan cerita tentang jenama melanggar peraturan — ini cerita tentang betapa banyak yang boleh dikatakan oleh sesuatu label makanan, secara teknikal, dengan benar, sambil masih meninggalkan ibu bapa dengan gambaran yang salah tentang apa yang sebenarnya masuk ke dalam badan anak mereka. <b_a>Peraturan diikuti. Maksudnya masih terlepas.</b_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Examples', 'ms', 'Contoh', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Feeding kids well felt, for a long time, like it came down to reading the front of a box. "No added sugar." "Rich in fibre." "Trusted by nutritionists." I believed the front the way most parents do — because turning a pack over and reading nine lines of ingredient text in six-point type isn''t something anyone has the time or patience for, standing in an aisle with a child pulling at your sleeve.', 'ms', 'Memberi anak makan dengan baik terasa, sekian lama, seperti bergantung pada membaca bahagian hadapan kotak. "Tanpa gula tambahan." "Kaya serat." "Dipercayai pakar pemakanan." Saya mempercayai bahagian hadapan seperti kebanyakan ibu bapa — kerana membalikkan pek dan membaca sembilan baris teks bahan dalam huruf enam mata bukanlah sesuatu yang ada masa atau kesabaran untuk dilakukan sesiapa, berdiri di lorong dengan anak yang menarik lengan baju anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
