INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Five lunchbox ideas for your child''s age, each scoring Good. Free, one email a week.', 'ms', 'Lima idea bekal untuk umur anak anda, masing-masing berskor Baik. Percuma, satu e-mel seminggu.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
