INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('For adults ICMR-NIN {#} gives men and women separately, each at sedentary, moderate and heavy work. Choose men or women, and the kind of work, on the Products and Scan pages; with neither chosen the average of men and women at sedentary work is used. Pregnant and lactating women are not scored yet.', 'ms', 'Bagi dewasa ICMR-NIN {#} memberi lelaki dan wanita secara berasingan, masing-masing pada kerja ringan, sederhana dan berat. Pilih lelaki atau wanita, dan jenis kerja, di laman Produk dan Imbas; jika tidak memilih kedua-duanya, purata lelaki dan wanita pada kerja ringan digunakan. Wanita hamil dan menyusu belum diberi skor.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('From various cooks and cookbooks, each credited to the person who wrote it. Scored for the age you pick. <b_a>Tap the heart on any recipe to save it.</b_a>', 'ms', 'Daripada pelbagai tukang masak dan buku masakan, setiap satu dikreditkan kepada orang yang menulisnya. Diberi skor untuk umur yang anda pilih. <b_a>Ketik hati pada mana-mana resipi untuk menyimpannya.</b_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('From {#} years the ICMR-NIN {#} table is by sex. On the Products and Scan pages, choose boys or girls to score for one of them; with neither chosen the average is used.', 'ms', 'Mulai {#} tahun jadual ICMR-NIN {#} dibahagikan mengikut jantina. Di laman Produk dan Imbas, pilih budak lelaki atau perempuan untuk memberi skor kepada salah satunya; jika tidak memilih kedua-duanya, purata digunakan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
