INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('It''s the same thing I was already doing at the shelf, turned into a rubric instead of kept in my head — ten numbers, the age bands they actually apply to, and the citations behind each one. It won''t tell you what to feed your kids. That''s still your call, and it should stay that way. It''ll just tell you, plainly, what''s actually in the pack before you decide.', 'ms', 'Ia perkara yang sama yang sudah saya lakukan di rak, dijadikan rubrik dan bukannya disimpan dalam kepala — sepuluh nombor, kumpulan umur yang benar-benar terpakai, dan petikan di sebalik setiap satu. Ia tidak akan memberitahu anda apa yang perlu diberi kepada anak anda. Itu masih keputusan anda, dan ia harus kekal begitu. Ia hanya akan memberitahu anda, dengan jelas, apa yang sebenarnya ada dalam pek sebelum anda membuat keputusan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan features recipes from public recipe sites, with the creator''s name, photo credit and a link back, and steps written in our own words. To ask permission we email the creator at the contact address published on their own site, once. We keep that address, our email, their reply, and a phone number if they choose to send one, only to record their permission and to reach them about sharing. We stop and remove their recipes and photos if they tell us to. Our reader for public pages is described at <a_a>KidPoshanBot</a_a>.', 'ms', 'KidPoshan memaparkan resipi daripada laman resipi awam, dengan nama pembuatnya, kredit foto dan pautan kembali, serta langkah yang ditulis dengan kata-kata kami sendiri. Untuk meminta kebenaran kami menghantar e-mel kepada pembuatnya di alamat hubungan yang diterbitkan di laman mereka sendiri, sekali. Kami menyimpan alamat itu, e-mel kami, balasan mereka, dan nombor telefon jika mereka memilih untuk menghantarnya, hanya untuk merekodkan kebenaran mereka dan menghubungi mereka tentang perkongsian. Kami berhenti dan mengalihkan resipi dan foto mereka jika mereka meminta. Pembaca kami untuk laman awam diterangkan di <a_a>KidPoshanBot</a_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan helps parents decide what to cook for their children by age, meal and season, and gives every recipe a Poshan Score. This page says what we collect, why, who sees it, and how to have it removed. For anything here, write to <a_a>kidposhan@gmail.com</a_a>.', 'ms', 'KidPoshan membantu ibu bapa memutuskan apa yang hendak dimasak untuk anak mereka mengikut umur, waktu makan dan musim, dan memberi setiap resipi Poshan Score. Laman ini menyatakan apa yang kami kumpulkan, mengapa, siapa yang melihatnya, dan cara untuk memadamkannya. Untuk apa-apa di sini, tulis kepada <a_a>kidposhan@gmail.com</a_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan is free for parents. If this recipe helped, ₹', 'ms', 'KidPoshan percuma untuk ibu bapa. Jika resipi ini membantu, ₹', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan is written for parents. Children should not give us their details.', 'ms', 'KidPoshan ditulis untuk ibu bapa. Kanak-kanak tidak boleh memberi butiran mereka kepada kami.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
