INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('No barcode found in that picture. Hold the barcode flat and steady inside the frame, then try again.', 'ms', 'Tiada kod bar ditemui dalam gambar itu. Pegang kod bar rata dan stabil di dalam bingkai, kemudian cuba lagi.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
