INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Not out of suspicion at first — more out of habit, the way you check a price tag twice. And the gap between what the front claimed and what the ingredient panel actually said kept showing up in places I didn''t expect. A "wholesome" muesli with sugar sitting a few ingredients down the list. A ketchup where tomato wasn''t even the first thing named. A seasoning sachet whose printed "serving size" was so small that the sodium math only looked reasonable if nobody actually used a full sachet in a meal.', 'ms', 'Pada mulanya bukan kerana curiga — lebih kerana kebiasaan, seperti menyemak tanda harga dua kali. Dan jurang antara apa yang didakwa bahagian hadapan dan apa yang sebenarnya dinyatakan panel bahan terus muncul di tempat yang tidak saya jangka. Muesli yang "berkhasiat" dengan gula beberapa bahan ke bawah dalam senarai. Sos tomato yang tomatonya bukan pun benda pertama disebut. Sachet perisa yang "saiz sajian" tercetaknya begitu kecil sehingga pengiraan natriumnya hanya kelihatan munasabah jika tiada siapa menggunakan sachet penuh dalam satu hidangan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
