INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Photos you send are kept to score the pack. They may be shown with the pack on the Products page after our team has checked it, so please photograph only the pack, not people. We keep no name, number or address with a scan. See the <a_a>privacy page</a_a>.', 'ms', 'Foto yang anda hantar disimpan untuk memberi skor kepada pek. Ia mungkin dipaparkan bersama pek di laman Produk selepas pasukan kami menyemaknya, jadi sila ambil foto pek sahaja, bukan orang. Kami tidak menyimpan nama, nombor atau alamat bersama imbasan. Lihat <a_a>laman privasi</a_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
