INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is a beta built with parents: where the numbers come from, what not yet checked means, and how to add a pack or report a mistake.', 'ms', 'Poshan Score ialah beta yang dibina bersama ibu bapa: dari mana nombor datang, apa maksud belum disemak, dan cara menambah pek atau melaporkan kesilapan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
