INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification, and no brand pays to be here. Label values come from the pack''s own page or Open Food Facts. The age guide is general, not medical advice.', 'ms', 'Poshan Score ialah penilaian bebas, bukan pensijilan, dan tiada jenama membayar untuk berada di sini. Nilai label datang daripada laman pek itu sendiri atau Open Food Facts. Panduan umur bersifat umum, bukan nasihat perubatan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification, and the age guide is general, not medical advice.', 'ms', 'Poshan Score ialah penilaian bebas, bukan pensijilan, dan panduan umur bersifat umum, bukan nasihat perubatan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification. The age guide is general and cautious. It is not medical advice.', 'ms', 'Poshan Score ialah penilaian bebas, bukan pensijilan. Panduan umur bersifat umum dan berhati-hati. Ia bukan nasihat perubatan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is that habit, written down.', 'ms', 'Poshan Score ialah tabiat itu, yang ditulis.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
