INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan the barcode on any packaged food and see its Poshan Score for your child''s age. If we do not know the pack yet, photograph the front and back and we will score it.', 'ms', 'Imbas kod bar pada mana-mana makanan berpek dan lihat Poshan Score-nya untuk umur anak anda. Jika kami belum mengenali pek itu, ambil foto hadapan dan belakang dan kami akan memberi skor kepadanya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan the barcode on any packaged food. If we know the pack you see its Poshan Score straight away. If we do not, photograph the front and the back of the pack and we score it for you, then add it for every parent once our team has checked it.', 'ms', 'Imbas kod bar pada mana-mana makanan berpek. Jika kami mengenali pek yang anda lihat, anda terus nampak Poshan Score-nya. Jika tidak, ambil foto hadapan dan belakang pek dan kami memberi skor untuk anda, kemudian menambahnya untuk semua ibu bapa setelah pasukan kami menyemaknya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
