INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Thank you. We do not score that kind of food yet.', 'ms', 'Terima kasih. Kami belum memberi skor kepada jenis makanan itu.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
