INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('That photo could not be used. Please take it again.', 'ms', 'Foto itu tidak dapat digunakan. Sila ambil semula.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The Poshan meter', 'ms', 'Meter Poshan', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The age groups are the ones the ICMR-NIN {#} table uses: {#}–{#}, {#}–{#} and {#}–{#} years; boys and girls at {#}–{#}, {#}–{#} and {#}–{#}; and adults, men and women at sedentary, moderate or heavy work. Under {#} months we use the {#}–{#} year reference. Tap a group to see its reference numbers. Pregnant and lactating women are not scored yet.', 'ms', 'Kumpulan umur ialah yang digunakan jadual ICMR-NIN {#}: {#}–{#}, {#}–{#} dan {#}–{#} tahun; budak lelaki dan perempuan pada {#}–{#}, {#}–{#} dan {#}–{#}; serta dewasa, lelaki dan wanita pada kerja ringan, sederhana atau berat. Di bawah {#} bulan kami menggunakan rujukan {#}–{#} tahun. Ketik satu kumpulan untuk melihat nombor rujukannya. Wanita hamil dan menyusu belum diberi skor.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The aisle', 'ms', 'Lorong kedai', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The amount of sodium is held constant. Only the age band''s daily reference changes.', 'ms', 'Jumlah natrium dikekalkan. Hanya rujukan harian kumpulan umur yang berubah.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The barcode could not be read from that photo. Try again with the barcode filling the picture, or type the number under it.', 'ms', 'Kod bar tidak dapat dibaca daripada foto itu. Cuba lagi dengan kod bar memenuhi gambar, atau taip nombor di bawahnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The barcode reader could not load. Type the number under the barcode instead.', 'ms', 'Pembaca kod bar tidak dapat dimuatkan. Taip nombor di bawah kod bar sebaliknya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The camera could not start. Type the number under the barcode instead, or take a photo of the barcode.', 'ms', 'Kamera tidak dapat dimulakan. Taip nombor di bawah kod bar, atau ambil foto kod bar.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The camera is switched off for this page. Allow it in the browser, or type the number under the barcode.', 'ms', 'Kamera dimatikan untuk laman ini. Benarkan dalam pelayar, atau taip nombor di bawah kod bar.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The camera takes the photo by itself when the picture is sharp and still. You can also tap the button.', 'ms', 'Kamera mengambil foto sendiri apabila gambar jelas dan senyap. Anda juga boleh mengetik butangnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
