INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same label can pass at one age and fail at another, so the score out of {#} changes too. Pick the age group on the <a_a>Products page</a_a> and the whole catalogue is re-scored for that age.', 'ms', 'Label yang sama boleh lulus pada satu umur dan gagal pada umur lain, jadi skor daripada {#} juga berubah. Pilih kumpulan umur di <a_a>laman Produk</a_a> dan seluruh katalog diberi skor semula untuk umur itu.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same product at each age', 'ms', 'Produk yang sama pada setiap umur', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same rubric for every product on the shelf — theirs and ours. Ten yes-or-no checks, each worth {#} points, worked out for the age group (and, from {#} years, boy or girl, man or woman) and one realistic serving. Six are numbers off the label, measured against that group''s daily reference. Three are checks on the ingredient list. The tenth fails if the sugar, sodium or saturated-fat check fails. Full citations and thresholds on the <a_a>Age & Metrics</a_a> page.', 'ms', 'Rubrik yang sama untuk setiap produk di rak — milik mereka dan milik kami. Sepuluh semakan ya-atau-tidak, masing-masing bernilai {#} mata, dikira untuk kumpulan umur (dan, mulai {#} tahun, budak lelaki atau perempuan, lelaki atau wanita) dan satu sajian yang realistik. Enam ialah nombor pada label, diukur terhadap rujukan harian kumpulan itu. Tiga ialah semakan pada senarai bahan. Yang kesepuluh gagal jika semakan gula, natrium atau lemak tepu gagal. Petikan penuh dan ambang ada di laman <a_a>Umur & Metrik</a_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The scanner could not load.', 'ms', 'Pengimbas tidak dapat dimuatkan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The site runs on Cloudflare (hosting and database). We use Cloudflare''s AI service to rewrite recipe steps and Tavily to search the web for recipe pages; neither receives your name, number or email. Gmail (Google) is used only as described above. We do not sell or rent your information.', 'ms', 'Laman ini berjalan di Cloudflare (pengehosan dan pangkalan data). Kami menggunakan perkhidmatan AI Cloudflare untuk menulis semula langkah resipi dan Tavily untuk mencari laman resipi di web; kedua-duanya tidak menerima nama, nombor atau e-mel anda. Gmail (Google) hanya digunakan seperti diterangkan di atas. Kami tidak menjual atau menyewakan maklumat anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The ten checks, each a yes or no', 'ms', 'Sepuluh semakan, masing-masing ya atau tidak', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The ten checks, the limits for every age group, and how to read the rubric.', 'ms', 'Sepuluh semakan, had bagi setiap kumpulan umur, dan cara membaca rubrik.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The ten marks', 'ms', 'Sepuluh markah', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('There''s enough of that already — inconsistent from one Instagram post to the next, and rarely benchmarked against anything more solid than a personal preference. What I wanted was the same numbers, read the same way, every time, checked against something real — <b_a>ICMR-NIN''s dietary guidelines, FSSAI''s own regulations</b_a> — instead of a brand''s marketing copy. And I wanted our own products held to that same bar, not just everyone else''s on the shelf.', 'ms', 'Sudah cukup banyak yang seperti itu — tidak konsisten daripada satu hantaran Instagram ke yang seterusnya, dan jarang dibandingkan dengan sesuatu yang lebih kukuh daripada citarasa peribadi. Apa yang saya mahu ialah nombor yang sama, dibaca dengan cara yang sama, setiap kali, disemak terhadap sesuatu yang nyata — <b_a>garis panduan pemakanan ICMR-NIN, peraturan FSSAI sendiri</b_a> — dan bukannya teks pemasaran sesuatu jenama. Dan saya mahu produk kami sendiri dipegang pada standard yang sama, bukan hanya produk orang lain di rak.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('These photos are of a pack I have. I am happy for KidPoshan to show them and use them to score this pack.', 'ms', 'Foto-foto ini ialah pek yang saya miliki. Saya bersetuju KidPoshan menunjukkannya dan menggunakannya untuk memberi skor kepada pek ini.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('They are saved on this phone now, and nobody else can see them. To open them on another phone or computer, confirm your mobile number with a one-time code. We do not ask for an email.', 'ms', 'Ia kini disimpan pada telefon ini, dan tiada orang lain boleh melihatnya. Untuk membukanya pada telefon atau komputer lain, sahkan nombor telefon bimbit anda dengan kod sekali guna. Kami tidak meminta e-mel.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This browser cannot use the camera here. Type the number under the barcode instead, or take a photo of the barcode.', 'ms', 'Pelayar ini tidak dapat menggunakan kamera di sini. Taip nombor di bawah kod bar, atau ambil foto kod bar.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
