INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This pack is on the', 'ms', 'Pek ini ada di', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This photo looks blurred. Please retake it, with the phone steady and the label in good light.', 'ms', 'Foto ini kelihatan kabur. Sila ambil semula, dengan telefon stabil dan label di bawah cahaya yang baik.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
