INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This score is ready to read now. The pack joins the Products page, for every parent, once our team has checked the label.', 'ms', 'Skor ini sedia dibaca sekarang. Pek akan menyertai laman Produk, untuk semua ibu bapa, setelah pasukan kami menyemak labelnya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This started as a parent''s habit before it became a rubric. Here''s the version without the spreadsheets, the age bands, or the citations.', 'ms', 'Ini bermula sebagai tabiat seorang ibu atau bapa sebelum menjadi rubrik. Inilah versi tanpa hamparan, kumpulan umur atau petikan.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Tick "To buy" on an ingredient and it appears here, grouped under each store.', 'ms', 'Tanda "Perlu dibeli" pada sesuatu bahan dan ia muncul di sini, dikumpulkan di bawah setiap kedai.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Tick "To buy" on an ingredient to build a shopping list.', 'ms', 'Tanda "Perlu dibeli" pada sesuatu bahan untuk membina senarai membeli-belah.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('To buy', 'ms', 'Perlu dibeli', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('To send those permission requests and read the replies, KidPoshan connects to the Google account <b_a>kidposhan@gmail.com</b_a> through the Gmail API, with permission only to <b_b>send email</b_b> and to <b_c>read the replies to the emails we sent</b_c>. We do not read any other mail, we do not share Gmail data with anyone, we do not use it for advertising, and it is not used to train any AI model. A reply is read by our systems to record whether the creator agreed and any phone number given, and by the owner of the site. KidPoshan''s use of information received from Google APIs adheres to the <a_d>Google API Services User Data Policy</a_d>, including its Limited Use requirements.', 'ms', 'Untuk menghantar permintaan kebenaran itu dan membaca balasannya, KidPoshan bersambung ke akaun Google <b_a>kidposhan@gmail.com</b_a> melalui API Gmail, dengan kebenaran hanya untuk <b_b>menghantar e-mel</b_b> dan <b_c>membaca balasan kepada e-mel yang kami hantar</b_c>. Kami tidak membaca mel lain, kami tidak berkongsi data Gmail dengan sesiapa, kami tidak menggunakannya untuk pengiklanan, dan ia tidak digunakan untuk melatih mana-mana model AI. Balasan dibaca oleh sistem kami untuk merekodkan sama ada pembuat resipi bersetuju dan sebarang nombor telefon yang diberi, dan oleh pemilik laman. Penggunaan maklumat yang diterima KidPoshan daripada Google APIs mematuhi <a_d>Google API Services User Data Policy</a_d>, termasuk keperluan Limited Use-nya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Today on Poshan Score', 'ms', 'Hari ini di Poshan Score', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
