INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Type a <span_a>food</span_a> · a <span_b>brand</span_b> · or a <span_c>recipe link</span_c>', 'ms', 'Taip <span_a>makanan</span_a> · <span_b>jenama</span_b> · atau <span_c>pautan resipi</span_c>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Type the number printed under the barcode.', 'ms', 'Taip nombor yang dicetak di bawah kod bar.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Under {#} months there is no published reference band, so the <b_a>{#}–{#} years</b_a> reference numbers are used. Only plain foods meant for babies are scored: a product with added sugar or salt is shown as “Not for under {#}”, not as a number.', 'ms', 'Di bawah {#} bulan tiada julat rujukan diterbitkan, jadi nombor rujukan <b_a>{#}–{#} tahun</b_a> digunakan. Hanya makanan biasa untuk bayi diberi skor: produk dengan gula atau garam tambahan ditunjukkan sebagai “Bukan untuk di bawah {#}”, bukan sebagai nombor.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
