INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We are still adding packs. If yours is missing, scan it and we will score it from your photos.', 'ms', 'Kami masih menambah pek. Jika pek anda tiada, imbasnya dan kami akan memberi skor daripada foto anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We confirm each payment against our UPI account before counting it. Payment is optional and does not unlock anything.', 'ms', 'Kami mengesahkan setiap pembayaran terhadap akaun UPI kami sebelum mengiranya. Pembayaran adalah pilihan dan tidak membuka apa-apa.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We could not check that link.', 'ms', 'Kami tidak dapat menyemak pautan itu.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
