INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We keep no name or phone number with a scan or a report. More is on the <a_a>privacy page</a_a>.', 'ms', 'Kami tidak menyimpan nama atau nombor telefon bersama imbasan atau laporan. Maklumat lanjut ada di <a_a>laman privasi</a_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We keep what you give us for as long as the site runs, or until you ask us to delete it. You can ask us to show you, correct or delete your name, number, email, ratings or remarks, or a creator''s details, by writing to <a_a>kidposhan@gmail.com</a_a>. We will deal with it promptly.', 'ms', 'Kami menyimpan apa yang anda berikan selagi laman ini berjalan, atau sehingga anda meminta kami memadamkannya. Anda boleh meminta kami menunjukkan, membetulkan atau memadamkan nama, nombor, e-mel, penilaian atau komen anda, atau butiran pembuat resipi, dengan menulis kepada <a_a>kidposhan@gmail.com</a_a>. Kami akan menanganinya dengan segera.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We use these to know who rated or wrote a remark. Your mobile number is never shown on the site.', 'ms', 'Kami menggunakan ini untuk mengetahui siapa yang menilai atau menulis komen. Nombor telefon bimbit anda tidak pernah dipaparkan di laman.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
