INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('When we are wrong, we want to hear it. Every pack has a <b_a>Report a mistake</b_a> button.', 'ms', 'Apabila kami salah, kami mahu mendengarnya. Setiap pek mempunyai butang <b_a>Laporkan kesilapan</b_a>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('When you send photos you tick a box to say they are of a pack you have and that KidPoshan may show them and use them to score the pack. Please photograph only the pack, not people.', 'ms', 'Apabila anda menghantar foto anda menanda kotak untuk menyatakan foto itu ialah pek yang anda miliki dan KidPoshan boleh menunjukkannya serta menggunakannya untuk memberi skor kepada pek itu. Sila ambil foto pek sahaja, bukan orang.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
