INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Why we built the Poshan Score: a plain, independent way to read what is really on the back of a pack, scored for each age group from {#} months to adults.', 'ms', 'Mengapa kami membina Poshan Score: cara yang mudah dan bebas untuk membaca apa yang sebenarnya ada di belakang pek, diberi skor bagi setiap kumpulan umur dari {#} bulan hingga dewasa.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
