INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no Class II preservative is named in the ingredients: the ones parents recognise least, checked most.', 'ms', 'Ya jika tiada bahan pengawet Kelas II dinamakan dalam bahan: yang paling kurang dikenali ibu bapa, paling kerap disemak.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no artificial colour, flavour enhancer or sweetener is named, by INS number or by name.', 'ms', 'Ya jika tiada pewarna tiruan, penguat perisa atau pemanis dinamakan, mengikut nombor INS atau nama.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no hydrogenated oil, vanaspati or margarine is listed. FSSAI caps industrial trans fat at {#}% of oils and fats, the same at every age.', 'ms', 'Ya jika tiada minyak terhidrogen, vanaspati atau marjerin disenaraikan. FSSAI menghadkan lemak trans industri kepada {#}% daripada minyak dan lemak, sama pada setiap umur.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving gives at least {#}% of the day''s fibre for that age group, from ICMR-NIN {#}.', 'ms', 'Ya jika satu sajian memberi sekurang-kurangnya {#}% serat harian untuk kumpulan umur itu, daripada ICMR-NIN {#}.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving gives at least {#}% of the day''s protein for that age group, sex and kind of work, from the ICMR-NIN {#} RDAs.', 'ms', 'Ya jika satu sajian memberi sekurang-kurangnya {#}% protein harian untuk kumpulan umur, jantina dan jenis kerja itu, daripada RDA ICMR-NIN {#}.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s free-sugar limit for that age group ({#}% for snacks and sweets). The limit is {#}% of energy, from WHO, on ICMR-NIN energy.', 'ms', 'Ya jika satu sajian kekal di bawah {#}% had gula bebas harian untuk kumpulan umur itu ({#}% untuk snek dan manisan). Hadnya ialah {#}% tenaga, daripada WHO, pada tenaga ICMR-NIN.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s limit ({#}% for snacks and sweets). The limit is WHO''s under {#}% of energy.', 'ms', 'Ya jika satu sajian kekal di bawah {#}% had harian ({#}% untuk snek dan manisan). Hadnya ialah had WHO di bawah {#}% tenaga.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s sodium ({#}% for snacks and sweets). ICMR-NIN''s adult limit is {#} mg; for children we scale it down by energy.', 'ms', 'Ya jika satu sajian kekal di bawah {#}% natrium harian ({#}% untuk snek dan manisan). Had dewasa ICMR-NIN ialah {#} mg; untuk kanak-kanak kami menurunkannya mengikut tenaga.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if the first ingredient is a real food, not sugar or a refined flour, starch or fat.', 'ms', 'Ya jika bahan pertama ialah makanan sebenar, bukan gula atau tepung, kanji atau lemak yang diproses.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes only if the sugar, sodium and saturated-fat checks all pass. Echoes FSSAI''s pending front-of-pack warning for foods high in fat, sugar or salt.', 'ms', 'Ya hanya jika semakan gula, natrium dan lemak tepu semuanya lulus. Menyerupai amaran hadapan pek FSSAI yang masih dicadangkan untuk makanan tinggi lemak, gula atau garam.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Your email is optional. If you leave it, we use it once, to thank you when your pack is checked, or to tell you what we did about a report. We use it for nothing else, and we do not share it.', 'ms', 'E-mel anda adalah pilihan. Jika anda memberinya, kami menggunakannya sekali, untuk berterima kasih apabila pek anda disemak, atau memberitahu apa yang kami lakukan tentang laporan. Kami tidak menggunakannya untuk apa-apa lagi, dan kami tidak berkongsinya.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
