INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('{#} kids'' recipes from cooks and cookbooks, each with a Poshan Score for every age from toddlers to adults. Breakfast, lunchbox, lunch, snacks and dinner, vegetarian, Jain and non-vegetarian.', 'ms', '{#} resipi kanak-kanak daripada tukang masak dan buku masakan, masing-masing dengan Poshan Score untuk setiap umur daripada kanak-kanak kecil hingga dewasa. Sarapan, bekal, makan tengah hari, snek dan makan malam, vegetarian, Jain dan bukan vegetarian.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('{#} recipes from various cooks and cookbooks, each credited to the person who wrote it. Every recipe has a Poshan Score out of {#}, worked out for one serving and for every age group from toddlers to adults. Open one to see the ingredients and the score for your child''s age, save it, and plan your week.', 'ms', '{#} resipi daripada pelbagai tukang masak dan buku masakan, masing-masing dikreditkan kepada orang yang menulisnya. Setiap resipi mempunyai Poshan Score daripada {#}, dikira bagi satu sajian dan bagi setiap kumpulan umur daripada kanak-kanak kecil hingga dewasa. Buka satu untuk melihat bahan dan skor untuk umur anak anda, simpan, dan rancang minggu anda.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
